/* HERO SPOTLIGHT (V5, ChatGPT steer) — the featured card is a living
   spotlight: it crossfades through the catalog pieces that carry art,
   ~6s a piece, with a light-sweep sheen. Controls: prev/next arrows and
   dots (tap to jump). Pauses on hover/focus. prefers-reduced-motion:
   no auto-advance, no sweep (CSS kills the sheen too). The caption and
   the card's hue glow track the piece on stage. */
function heroSpotlight(){let pieces=SEED.filter(a=>a.img);if(!pieces.length)return '';let ix=Math.max(0,Math.min(state.spotIx||0,pieces.length-1));let cur=pieces[ix];
let slides=pieces.map((a,i)=>'<img class="spot-img'+(i===ix?' on':'')+'" src="'+safe(a.img)+'" alt="'+safe(a.title)+' by '+safe(a.artist)+'" data-spot-img="'+i+'"'+(i===ix?'':' loading="lazy"')+'>').join('');
let dots=pieces.map((a,i)=>'<button type="button" class="spot-dot'+(i===ix?' on':'')+'" data-action="spot-dot" data-ix="'+i+'" aria-label="Show '+safe(a.title)+'"></button>').join('');
return '<figure class="hero-feature" id="heroFeature" style="--spot-hue:'+catHue(cur.category)+'"><div class="hero-art" id="heroArt" style="background:'+catBg(cur.category)+'"><a class="hero-art-link" id="heroArtLink" href="#/art/'+cur.id+'" aria-label="View '+safe(cur.title)+' by '+safe(cur.artist)+'">'+slides+'<span class="sheen" aria-hidden="true"></span><span class="art-overlay"></span></a><span class="tag" id="heroTag">✦ '+safe(cur.tag)+'</span><div class="spot-ctl"><button type="button" class="spot-arrow" data-action="spot-prev" aria-label="Previous artwork">‹</button><div class="spot-dots">'+dots+'</div><button type="button" class="spot-arrow" data-action="spot-next" aria-label="Next artwork">›</button></div></div><figcaption><div><b id="heroCapTitle">'+safe(cur.title)+'</b><span id="heroCapMeta">by '+safe(cur.artist)+' · '+safe(cur.medium)+'</span></div><div class="hero-price" id="heroCapPrice">'+money(cur.price)+'</div></figcaption></figure>'}
function spotPieces(){return SEED.filter(a=>a.img)}
function spotShow(ix){try{let pieces=spotPieces();if(!pieces.length)return;ix=((ix%pieces.length)+pieces.length)%pieces.length;state.spotIx=ix;let fig=document.getElementById('heroFeature');if(!fig||!fig.querySelectorAll)return;let a=pieces[ix];
 if(fig.style&&fig.style.setProperty)fig.style.setProperty('--spot-hue',catHue(a.category));
 fig.querySelectorAll('[data-spot-img]').forEach(function(im){if(im.classList)im.classList.toggle('on',Number(im.dataset&&im.dataset.spotImg)===ix)});
 fig.querySelectorAll('.spot-dot').forEach(function(d,i){if(d.classList)d.classList.toggle('on',i===ix)});
 let art=document.getElementById('heroArt');if(art&&art.style)art.style.background=catBg(a.category);
 let link=document.getElementById('heroArtLink');if(link&&link.setAttribute){link.setAttribute('href','#/art/'+a.id);link.setAttribute('aria-label','View '+a.title+' by '+a.artist)}
 let t=document.getElementById('heroCapTitle');if(t)t.textContent=a.title;
 let m=document.getElementById('heroCapMeta');if(m)m.textContent='by '+a.artist+' · '+a.medium;
 let p=document.getElementById('heroCapPrice');if(p)p.textContent=money(a.price);
 let tg=document.getElementById('heroTag');if(tg)tg.textContent='✦ '+a.tag}catch(e){}}
let spotTimer=null,spotPaused=false;
function spotInit(){try{if(spotTimer){clearInterval(spotTimer);spotTimer=null}
 let fig=document.getElementById('heroFeature');if(!fig||!fig.addEventListener)return;if(spotPieces().length<2)return;
 spotPaused=false;
 fig.addEventListener('mouseenter',function(){spotPaused=true});
 fig.addEventListener('mouseleave',function(){spotPaused=false});
 fig.addEventListener('focusin',function(){spotPaused=true});
 fig.addEventListener('focusout',function(){spotPaused=false});
 let reduce=false;try{reduce=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)}catch(e){}
 if(reduce)return;
 spotTimer=setInterval(function(){if(!spotPaused)spotShow((state.spotIx||0)+1)},6000);
 if(spotTimer&&spotTimer.unref)spotTimer.unref()}catch(e){}}
function explore(savedOnly=false){let items=all().filter(a=>(!savedOnly||likes().includes(a.id))&&(state.category==='All art'||a.category===state.category)&&(`${a.title} ${a.artist} ${USERNAMES[a.artist]||''} ${a.category}`.toLowerCase().includes(state.query.toLowerCase().replace('@',''))));if(state.sort==='Price: low to high')items.sort((a,b)=>a.price-b.price);if(state.sort==='Price: high to low')items.sort((a,b)=>b.price-a.price);if(state.sort==='Newest')items.reverse();return `<div class="page-hero" style="--ph:#8B7CFF"><div class="shell"><div class="eyebrow">DISCOVER YOUR NEXT OBSESSION</div><h1 class="page-title">${savedOnly?'YOUR SAVED':`EXPLORE THE <span class="paint">UNEXPECTED.</span>`}</h1><p class="sub">Original art. Electric perspectives. Real conversations with independent artists.</p></div></div><section class="section"><div class="shell"><div class="pills scroll">${['All art',...CATEGORIES].map(n=>`<button class="pill ${n===state.category?'active':''}" data-action="category" data-cat="${safe(n)}" style="--pill-hue:${catHue(n)}"${n===state.category&&PRISM_CATS.indexOf(n)>=0?' data-prism="1"':''}>${safe(n)}</button>`).join('')}</div><div class="filters"><input class="field" id="searchArt" value="${safe(state.query)}" placeholder="Search artwork, creators, styles…" aria-label="Search artwork"><select id="catArt" aria-label="Category">${['All art','Painting','Digital Art','Illustration','Drawing & Sketch','Photography','Sculpture','Mixed Media','Collage','Printmaking','Prints & Posters','Ceramics','Textile & Fiber Art','Glass Art','Wood Art','Metal Art','Resin Art','Paper Art','Calligraphy & Lettering','Street Art & Murals','Tattoo Flash','Custom Portraits','Pet Portraits','Anime & Manga Style','3D & CGI Art','Cosplay','Pottery','Character Design','Commissions','Outfit Design'].map(n=>`<option ${n===state.category?'selected':''}>${n}</option>`).join('')}</select><select id="sortArt" aria-label="Sort artwork">${['Featured','Newest','Price: low to high','Price: high to low'].map(n=>`<option ${n===state.sort?'selected':''}>${n}</option>`).join('')}</select></div><div class="art-grid">${items.map(artCard).join('')}</div>${items.length?'':'<div class="empty">Nothing in this collection yet. Try another filter.</div>'}</div></section>`}
function detail(id){let a=all().find(x=>String(x.id)===String(id));if(!a)return notFound();return `<section class="section" style="padding-top:0"><div class="detail-band" style="${a.img?('background-image:url('+safe(a.img)+')'):artLook(a)}" role="img" aria-label="${safe(a.title)} by ${safe(a.artist)}"></div><div class="shell two-col" style="margin-top:36px"><div class="detail-art" style="${a.img?('background:'+catBg(a.category)):artLook(a)}">${a.img?'<img class="art-photo" src="'+safe(a.img)+'" alt="'+safe(a.title)+' by '+safe(a.artist)+'">':'◉'}</div><div class="detail-side"><div class="eyebrow">${safe(a.category)} / ${safe(a.tag)}</div><h1>${safe(a.title)}</h1><div class="meta">An artwork by <strong style="color:#fff">${safe(a.artist)}</strong></div><div class="detail-price paint">${money(a.price)}</div><p>${safe(a.description)}</p><div class="chips"><span class="chip">✦ ${safe(a.medium)}</span><span class="chip">↗ Direct artist messaging</span><span class="chip">♡ Independent creator</span>${slotsChip(a.artist)}</div><div class="actions"><button class="primary" data-action="add" data-id="${a.id}">ADD TO CART +</button><button class="outline" data-action="contact" data-artist="${safe(a.artist)}">MESSAGE THE ARTIST ✉</button><button class="outline" data-action="like" data-id="${a.id}">${likes().includes(a.id)?'♥ SAVED':'♡ SAVE'}</button><button class="outline" data-action="share-piece" data-id="${a.id}">SHARE CARD ↗</button></div><div class="notice">Prototype listing: checkout is simulated. Real payments, shipping, and identity checks require production integration.</div></div></div></section><section class="section alt"><div class="shell"><div class="section-top"><h2 class="section-title">KEEP <span class="paint">EXPLORING.</span></h2></div><div class="art-grid">${all().filter(x=>x.id!==a.id).slice(0,4).map(artCard).join('')}</div></div></section>`}
function normName(u){return String(u||'').toLowerCase().replace(/0/g,'o').replace(/1/g,'i').replace(/3/g,'e').replace(/4/g,'a').replace(/5/g,'s').replace(/7/g,'t').replace(/@/g,'a').replace(/\$/g,'s')}
function usernameCheck(u){let raw=String(u||'').trim();if(raw.length<3||raw.length>20)return{ok:false,why:'short'};if(!/^[A-Za-z][A-Za-z0-9_.]*$/.test(raw))return{ok:false,why:'chars'};let n=normName(raw);let compact=n.replace(/[^a-z]/g,'');let hard=['fuck','shit','bitch','whore','slut','nigger','nigga','faggot','cunt','penis','vagina','porn','asshole','rape','pedophile','molester'];for(let w of hard){if(compact.indexOf(w)>=0)return{ok:false,why:'bad'}}let toks=n.split(/[^a-z]+/).filter(Boolean);let soft=['ass','dick','cock','sex','cum','tit','fag','nazi','kill'];for(let t of toks){if(soft.indexOf(t)>=0)return{ok:false,why:'bad'}}let reserved=['admin','support','official','paintedpython','painty','moderator','staff','flowermills','flower','owner','ceo'];if(reserved.indexOf(compact)>=0)return{ok:false,why:'reserved'};let taken=['novareyes','samrivera','riverquinn','kaisantos','arimoon','julescarter','milobanks','elimorgan'];if(taken.indexOf(compact)>=0)return{ok:false,why:'taken'};return{ok:true}}
function applyTheme(){let t=get(STORE.theme,'dark');if(document.body&&document.body.classList)document.body.classList.toggle('light',t==='light');let b=document.getElementById('themeBtn');if(b)b.textContent=t==='light'?'◑':'◐'}
applyTheme();
function bioCheck(t){let raw=String(t||'');if(/[^@\s]+@[^@\s]+\.[^@\s]+/.test(raw)||/(https?:\/\/|www\.)/i.test(raw)||/\b\d{3}[-.\s]\d{3}[-.\s]\d{4}\b/.test(raw)||/\b\d{7,}\b/.test(raw))return{ok:false,why:'contact'};let n=normName(raw.toLowerCase());let compact=n.replace(/[^a-z]/g,'');let hard=['fuck','shit','bitch','whore','slut','nigger','nigga','faggot','cunt','penis','vagina','porn','asshole','rape','killyourself','kys'];for(let w of hard){if(compact.indexOf(w)>=0)return{ok:false,why:'language'}}let toks=n.split(/[^a-z]+/).filter(Boolean);let soft=['ass','dick','cock','sex','cum','tit','fag','nazi'];for(let tk of toks){if(soft.indexOf(tk)>=0)return{ok:false,why:'language'}}return{ok:true}}
function picCheck(f){if(!f)return{ok:true};if(!/^image\//.test(f.type||''))return{ok:false,why:'type'};if(f.size>8*1024*1024)return{ok:false,why:'size'};return{ok:true}}
function avatarInner(example,nm){let p=get(STORE.profile,{});if(!example&&p.avatar)return '<img src="'+p.avatar+'" alt="Profile picture" style="width:100%;height:100%;object-fit:cover;border-radius:50%">';return safe(monogram(nm||'Nova Reyes'))}
function low(x){return String(x||'').toLowerCase()}
function getAccounts(){let a=get(STORE.accounts,null);if(!a){a=[];let k=get(STORE.known,{});if(k.username)a.push({email:k.email||'',username:k.username,pronouns:k.pronouns||'',dob:k.dob||'',bio:'',avatar:null});get(STORE.directory,[]).forEach(function(m){if(m.username&&!a.find(function(x){return low(x.username)===low(m.username)}))a.push({email:m.email||'',username:m.username,pronouns:m.pronouns||'',dob:m.dob||'',bio:m.bio||'',avatar:m.avatar||null})});let pr=get(STORE.profile,{}),su=get(STORE.signup,{});if(su.username){let ix=a.findIndex(function(x){return low(x.username)===low(su.username)});if(ix>=0){if(pr.bio)a[ix].bio=pr.bio;if(pr.avatar)a[ix].avatar=pr.avatar}}set(STORE.accounts,a)}return a}
function upsertAccount(rec){if(!rec||!rec.username)return;let a=getAccounts();let ix=a.findIndex(function(x){return low(x.username)===low(rec.username)});if(ix>=0)a[ix]=Object.assign({},a[ix],rec);else a.push(rec);set(STORE.accounts,a)}
function activateAccount(rec){set(STORE.signup,{email:rec.email||'',dob:rec.dob||'',pronouns:rec.pronouns||'',username:rec.username,at:Date.now()});set(STORE.profile,{bio:rec.bio||'',avatar:rec.avatar||null,at:Date.now()});set(STORE.known,{email:rec.email||'',dob:rec.dob||'',pronouns:rec.pronouns||'',username:rec.username});upsertMember({username:rec.username,email:rec.email||'',pronouns:rec.pronouns||'',dob:rec.dob||'',bio:rec.bio||'',avatar:rec.avatar||null})}
function accountRows(activeName){let a=getAccounts();if(!a.length)return '';let rows=a.map(function(r){let act=low(r.username)===low(activeName);return '<div style="display:flex;gap:12px;align-items:center;padding:10px 0;border-top:1px solid #3d3150"><div class="artist-avatar avatar-mono" style="width:44px;height:44px;font-size:16px;overflow:hidden;flex:none">'+(r.avatar?'<img src="'+r.avatar+'" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:50%">':safe(monogram(r.username)))+'</div><div style="flex:1;min-width:0"><b style="color:#fff">'+safe(r.username)+'</b><p class="meta" style="color:var(--cyan)">@'+safe(low(r.username))+(r.pronouns?' · '+safe(r.pronouns):'')+'</p></div>'+(act?'<span class="badge" style="background:#1d5c38;color:#b8ffd2">ACTIVE NOW</span>':'<button class="small-btn" data-action="login-as" data-u="'+safe(r.username)+'">LOG IN AS @'+safe(r.username.toUpperCase())+'</button>')+'</div>'}).join('');return '<div style="margin-bottom:18px"><h3 style="font-size:15px;letter-spacing:.06em">ACCOUNTS ON THIS DEVICE</h3><p class="sub" style="margin:6px 0 4px;font-size:13px">One tap switches — no typing, no password hunt.</p>'+rows+'</div>'}
function upsertMember(patch){if(!patch||!patch.username)return;let dir=get(STORE.directory,[]);let k=String(patch.username).toLowerCase();let ix=dir.findIndex(m=>String(m.username||'').toLowerCase()===k);if(ix>=0)dir[ix]=Object.assign({},dir[ix],patch);else dir.push(patch);set(STORE.directory,dir)}
function memberCard(m){let age=m.dob?ageFromDob(m.dob,new Date()):null;return '<div class="panel"><div class="artist-avatar avatar-mono" style="margin-bottom:15px;overflow:hidden">'+(m.avatar?'<img src="'+m.avatar+'" alt="Profile picture" style="width:100%;height:100%;object-fit:cover;border-radius:50%">':safe(monogram(m.username)))+'</div><h3>'+safe(m.username)+'</h3><p class="meta" style="color:var(--cyan);font-weight:700">@'+safe(String(m.username||'').toLowerCase())+'</p><p class="meta">'+(m.pronouns?safe(m.pronouns)+' · ':'')+'Member artist</p>'+(age!==null&&age!==undefined?'<div style="margin-top:6px">'+ageBadge(age)+'</div>':'')+(m.bio?'<p style="line-height:1.65;margin-top:9px;font-style:italic">“'+safe(m.bio)+'”</p>':'')+'<div style="margin-top:10px"><span class="badge" style="background:#1d5c38;color:#b8ffd2">✦ REAL MEMBER</span></div></div>'}
function ageFromDob(dob,now){let m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(dob||'');if(!m)return null;let y=+m[1],mo=+m[2],d=+m[3];if(mo<1||mo>12||d<1||d>31)return null;let age=now.getFullYear()-y;let before=(now.getMonth()+1<mo)||((now.getMonth()+1===mo)&&(now.getDate()<d));if(before)age--;if(age<0||age>120)return null;return age}
function sell(){let seller=get(STORE.seller,{});return `<div class="page-hero" style="--ph:#AFED66"><div class="shell"><div class="eyebrow">Your creative takeover begins here</div><h1 class="page-title">YOUR ART. <span class="paint">YOUR STAGE.</span></h1><p class="sub">A storefront built for artists who refuse to blend in. Create a listing in this interactive demo.</p></div></div><section class="section"><div class="shell two-col"><div><div class="panel" style="margin-bottom:22px;border:2px solid #7a3cff"><h2 class="section-title" style="font-size:30px">JOIN PAINTED <span class="paint">PYTHON.</span></h2><p class="sub" style="margin-bottom:14px">Create your account to sell your art — and to buy from the artists you love. Painted Python is for <b style="color:#fff">teenagers and adults only: you must be 13 or older to join.</b></p>${get(STORE.signup,null)?`<p style="line-height:1.7"><b style="color:#7CFC9A">✔ You’re signed up</b> as <b style="color:#fff">${safe(get(STORE.signup,{}).email||'')}</b>${get(STORE.signup,{}).username?' · @'+safe(get(STORE.signup,{}).username):''}${get(STORE.signup,{}).pronouns?' · '+safe(get(STORE.signup,{}).pronouns):''} in this browser. Your artist stage is reserved — real accounts activate at launch.</p><div class="actions" style="margin-top:12px"><button class="outline" data-action="signup-reset">USE A DIFFERENT EMAIL</button></div>`:`<form id="signupForm" class="form-grid"><div class="form-group"><label for="suUsername">CREATE YOUR USERNAME *</label><input id="suUsername" class="field" name="username" placeholder="e.g. rainbow.rebel_ink" required maxlength="20"></div><div class="form-group"><label for="suEmail">EMAIL ADDRESS *</label><input id="suEmail" class="field" name="email" type="email" placeholder="you@example.com" required maxlength="120"></div><div class="form-group"><label for="suDob">DATE OF BIRTH *</label><input id="suDob" class="field" name="dob" type="date" required></div><div class="form-group"><label for="suPronouns">PRONOUNS *</label><select id="suPronouns" class="field" name="pronouns" required><option value="">Choose your pronouns</option><option>She/Her</option><option>He/Him</option><option>They/Them</option></select></div><div class="full"><button class="primary" type="submit">SIGN UP — CREATE MY ACCOUNT ✦</button><p id="signupMsg" style="margin-top:10px;line-height:1.6" role="alert"></p><p class="form-note">One account for artists and customers. Under 13? We’ll be here when you’re ready — Painted Python does not create accounts for children under 13. Already have an account? <a class="text-link" href="#/login">LOG IN</a></p></div></form>`}</div><h2 class="section-title">LIST YOUR NEXT <span class="paint">MASTERPIECE.</span></h2><p class="sub">Publish a demonstration artwork instantly. Listings are stored in this browser only until Muse connects the real platform.</p><div class="panel"><form id="listingForm" class="form-grid"><div class="form-group"><label for="artistName">ARTIST / STUDIO NAME *</label><input id="artistName" class="field" name="artist" value="${safe(seller.artist||'')}" placeholder="Your creative identity" required maxlength="70"></div><div class="form-group"><label for="artTitle">ARTWORK TITLE *</label><input id="artTitle" class="field" name="title" placeholder="Name your artwork" required maxlength="100"></div><div class="form-group"><label for="artCategory">CATEGORY *</label><select id="artCategory" name="category"><option>Painting</option><option>Digital Art</option><option>Illustration</option><option>Drawing & Sketch</option><option>Photography</option><option>Sculpture</option><option>Mixed Media</option><option>Collage</option><option>Printmaking</option><option>Prints & Posters</option><option>Ceramics</option><option>Textile & Fiber Art</option><option>Glass Art</option><option>Wood Art</option><option>Metal Art</option><option>Resin Art</option><option>Paper Art</option><option>Calligraphy & Lettering</option><option>Street Art & Murals</option><option>Tattoo Flash</option><option>Custom Portraits</option><option>Pet Portraits</option><option>Anime & Manga Style</option><option>3D & CGI Art</option><option>Cosplay</option><option>Pottery</option><option>Character Design</option><option>Commissions</option><option>Outfit Design</option></select></div><div class="form-group"><label for="artPrice">PRICE (USD) *</label><input id="artPrice" class="field" name="price" type="number" min="1" max="100000" step="0.01" placeholder="250" required></div><div class="form-group"><label for="artMedium">MEDIUM / MATERIALS</label><input id="artMedium" class="field" name="medium" placeholder="Acrylic on canvas" maxlength="90"></div><div class="form-group"><label for="artEmoji">ARTWORK ICON (DEMO PREVIEW)</label><select id="artEmoji" name="symbol"><option>✦</option><option>◉</option><option>❖</option><option>♡</option><option>★</option><option>⬢</option><option>✿</option><option>◆</option></select></div><div class="form-group full"><label for="artDesc">TELL THE STORY *</label><textarea id="artDesc" name="description" placeholder="What inspired this piece? What should a buyer know?" required maxlength="900"></textarea></div><div class="form-group full"><label for="artColor">COLOR MOOD</label><select id="artColor" name="bg"><option value="linear-gradient(130deg,#fa2088,#4727c3,#07dff1)">Neon serpent</option><option value="linear-gradient(130deg,#ffb12b,#fa287f,#7638db)">Sunset fire</option><option value="linear-gradient(130deg,#02a4be,#9cf13e,#11266a)">Electric jungle</option></select></div><div class="full"><button class="primary" type="submit">PUBLISH DEMO LISTING ↗</button><p class="form-note">No images are uploaded in this front-end demo. Actual image upload, moderation, inventory, taxes, and payouts require backend services.</p></div></form></div></div><div class="panel" style="margin-bottom:20px"><h3 style="margin-bottom:6px">WHAT YOU'D KEEP</h3><p class="sub" style="margin-bottom:10px">The founder set our fees low on purpose. Move the price and see it plainly:</p><label for="keepPrice" style="font-size:12px;letter-spacing:1px">SALE PRICE — $<span id="keepVal">200</span></label><input id="keepPrice" type="range" min="25" max="2000" step="25" value="200" style="width:100%" oninput="keepCalc(this.value)"><div style="font-size:14px;line-height:1.9;margin-top:8px">${sellKeepLines()}</div><p class="form-note">Platform fee only: ${TIER_DATA.map(t=>t.fee+'%').join(' / ')} — every keep figure above is after platform fee. Processing shown at checkout — no surprises, ever.</p></div><div class="panel" style="margin-top:20px;border:2px solid #ffbd24"><div class="eyebrow" style="color:#ffd76a">✦ The Founding 100</div><h3 style="margin-bottom:6px">FIRST 100 ARTISTS: PYTHON AT $6/MO, LOCKED 24 MONTHS.</h3><p class="sub" style="margin-bottom:12px">Founding artists save $95.76 against standard Python across the lock, get 60 free days to onboard, and carry the Founding Python badge forever. Applications are open in this demo — stored on your device, first in line at launch.</p><a class="primary" href="#/founding100" style="text-decoration:none;display:inline-flex;align-items:center">APPLY FOR A FOUNDING SEAT →</a></div><aside><div class="artist-spot"><div class="artist-avatar avatar-mono">✦</div><div><h3>THE FUTURE LOOKS LIKE YOU.</h3><p class="sub">Own your aesthetic. Set your prices. Connect with people who get your work.</p></div></div><div class="steps" style="display:block;margin-top:20px"><div class="step"><span class="number">01</span><h3>SHOW YOUR WORK</h3><p>Illustrate your creative style with a strong gallery and a clear story.</p></div><div class="step" style="margin-top:14px"><span class="number">02</span><h3>CHAT WITH COLLECTORS</h3><p>Answer questions about the artwork, availability, and inspiration.</p></div><div class="step" style="margin-top:14px"><span class="number">03</span><h3>BUILD YOUR FOLLOWING</h3><p>Give people a place to discover your next release.</p></div></div></aside></div></section>`}
/* PROOF-OF-SELLING STUDIO (queue 7, 2026-10-26) — the seller dashboard that
   proves selling works by counting only what is stored. Every number on this
   page traces to a record in this browser: the member's listings
   (slither-listings-v1), their proposals (slither-proposals-v1), their alerts
   (slither-alerts-v1), the slot ledger (SLOT_SEED + accepted proposals), their
   tier (signup record) and their Founding application (slither-founding-v1).
   A number that cannot be traced is not printed — there is deliberately no
   audience metric here, because the demo records no audience. Replaces the
   placeholder dashboard(); #/dashboard keeps routing here so no door dies. */
function studioNames(su){
 let names=[];let push=function(n){n=String(n||'').trim();if(n&&!names.some(function(x){return low(x)===low(n)}))names.push(n)};
 if(su&&su.username){push(su.username);let dn=Object.keys(USERNAMES).find(function(n){return USERNAMES[n]===low(su.username)});if(dn)push(dn)}
 get(STORE.listings,[]).forEach(function(l){push(l.artist)});
 return names}
function studioProposals(names){
 let sent=[],received=[];
 allProposalsFlat().forEach(function(p){
  let asArtist=names.some(function(n){return low(n)===low(p.artist)});
  let asContact=names.some(function(n){return low(n)===low(p.contact)});
  if(asArtist)sent.push(Object.assign({},p,{dir:'SENT'}));
  else if(asContact)received.push(Object.assign({},p,{dir:'RECEIVED'}))});
 return{sent:sent,received:received,all:sent.concat(received)}}
function propStageOf(p){if(p.status==='DECLINED')return 'DECLINED';if(p.status==='COUNTERED')return 'PROPOSED';return STAGES.indexOf(p.stage)>=0?p.stage:'PROPOSED'}
function studioSlots(names){for(let n of names){let s=slotsFor(n);if(s)return{holder:n,total:s.total,used:s.used,open:s.open}}return null}
function studioFounding(su){
 if(!su)return null;
 let apps=foundingApps();
 let ix=apps.findIndex(function(a){return (su.username&&foundingNorm(a.name)===foundingNorm(su.username))||(su.email&&low(a.email)===low(su.email))});
 if(ix<0)return null;
 return{app:apps[ix],seat:apps.length-ix}}
/* NEXT BEST MOVE — exactly one prompt, computed from stored state only.
   Priority order (first match wins):
   1. first-listing — no listings stored: the stage is empty; listing is the game.
   2. queue-full — a slot ledger exists for the member and no slot is open.
   3. follow-up — at least one proposal waits at PROPOSED: move it in-thread.
   4. first-pitch — listings exist, pipeline empty: pitch a brief from Your Board.
   5. keep-feeding — work is already moving: pitch the next brief in your world. */
function studioNextMove(ctx){
 if(!ctx.own.length)return{key:'first-listing',title:'LIST YOUR FIRST PIECE.',body:'Your stage is empty — and an empty stage sells nothing. Your first listing takes about a minute, and everything else in this room wakes up behind it.',href:'#/sell',cta:'LIST A PIECE ↗'};
 if(ctx.slots&&ctx.slots.open===0)return{key:'queue-full',title:'YOU’RE BOOKED SOLID.',body:'Every one of your '+ctx.slots.total+' commission slots is spoken for — the queue is full because buyers said yes. Work the pipeline, deliver loud, and let the waitlist want you.',href:'#/messages',cta:'WORK THE PIPELINE →'};
 if(ctx.byStage['PROPOSED'])return{key:'follow-up',title:'FOLLOW UP IN THE THREAD.',body:ctx.byStage['PROPOSED']+(ctx.byStage['PROPOSED']===1?' proposal is':' proposals are')+' waiting at PROPOSED. Proposals move when the artist moves — open the thread and answer while the idea is still warm.',href:'#/messages',cta:'OPEN YOUR THREADS →'};
 if(!ctx.props.length){let m=ctx.matched;return{key:'first-pitch',title:'PITCH YOUR FIRST BRIEF.',body:m>0?('Your listings are live but the pipeline is empty — and '+m+' brief'+(m===1?'':'s')+' in your categories '+(m===1?'is':'are')+' already on the wall. Your Board has them waiting, aimed at your craft.'):'Your listings are live but the pipeline is empty. The Commission Board is the demand wall — go read it and pitch the brief that grabs you.',href:'#/board',cta:'OPEN THE BOARD →'}}
 return{key:'keep-feeding',title:'KEEP THE PIPELINE FED.',body:'Your commissions are already moving. The next brief in your world is on the Board — pitch it while your current work is in the studio, and the pipeline never runs dry.',href:'#/board',cta:'FIND THE NEXT BRIEF →'}}
function studio(){
 let su=get(STORE.signup,null);
 if(!su||!su.username){
  return `<div class="page-hero" style="--ph:#FFD166"><div class="shell"><div class="eyebrow">Artist studio · demo</div><h1 class="page-title">PROOF OF <span class="paint">SELLING.</span></h1><p class="sub">Your listings, your pipeline, your numbers — every figure in this room traces to a record stored in this browser. Nothing padded, nothing invented.</p></div></div><section class="section"><div class="shell"><div class="panel studio-door"><div class="eyebrow">Members only</div><h2 style="font-size:28px;margin:8px 0">THIS ROOM OPENS WHEN YOU SIGN IN.</h2><p class="sub" style="margin-bottom:16px">The studio is personal: it counts YOUR listings, YOUR proposals, YOUR alerts. Step into your account and it is already yours.</p><div class="actions"><a class="primary" href="#/login" style="text-decoration:none">LOG IN ✦</a><a class="outline" href="#/sell" style="text-decoration:none;display:inline-flex;align-items:center">CREATE YOUR ACCOUNT →</a></div></div></div></section>`}
 let names=studioNames(su);
 let own=get(STORE.listings,[]);
 let pr=studioProposals(names);let props=pr.all;
 let byStage={};props.forEach(function(p){let s=propStageOf(p);byStage[s]=(byStage[s]||0)+1});
 let slots=studioSlots(names);
 let unread=unreadAlerts();
 let cats=memberCategories();
 let matched=cats.length?allBriefs().filter(function(b){return cats.indexOf(b.category)>=0}).length:0;
 let move=studioNextMove({own:own,props:props,byStage:byStage,slots:slots,matched:matched});
 let tierName=currentArtistTier();let tier=TIER_DATA.find(function(t){return t.name===tierName})||TIER_DATA[0];
 let fnd=studioFounding(su);
 let stats='<div class="stat" data-stat="listings"><b>'+own.length+'</b><span>YOUR LISTINGS LIVE</span></div>'
  +(slots?'<div class="stat" data-stat="slots"><b>'+slots.open+' of '+slots.total+'</b><span>COMMISSION SLOTS OPEN</span></div>':'')
  +'<div class="stat" data-stat="proposals"><b>'+props.length+'</b><span>PROPOSALS IN YOUR PIPELINE</span></div>'
  +'<div class="stat" data-stat="alerts"><b>'+unread+'</b><span>UNREAD ALERTS</span></div>';
 let listRows=own.length?own.map(function(a){return '<div class="list-row"><div class="list-thumb" style="'+artLook(a)+'">'+(a.img?'<img src="'+safe(a.img)+'" alt="">':'◉')+'</div><div class="list-info"><strong>'+safe(a.title)+'</strong><small>'+money(a.price)+' · '+safe(a.category)+' · '+safe(a.tag||'Just listed')+'</small></div><span class="badge" style="background:#1d5c38;color:#b8ffd2">● LIVE</span><a class="mini-btn" href="#/art/'+a.id+'">OPEN</a><button class="mini-btn" data-action="delete" data-id="'+a.id+'">DELETE</button></div>'}).join('')
  :'<div class="empty">Your stage is empty — list your first piece and it hangs here, live, in front of every collector who walks the wall.<div class="actions" style="justify-content:center;margin-top:14px"><a class="primary" href="#/sell" style="text-decoration:none">LIST YOUR FIRST PIECE ↗</a></div></div>';
 let pipeHtml='';
 if(!props.length){
  pipeHtml='<div class="empty">No proposals in your pipeline yet. Proposals are born on the Commission Board — pitch a brief, or open a thread and build one.<div class="actions" style="justify-content:center;margin-top:14px"><a class="primary" href="#/board" style="text-decoration:none">SEE THE WALL →</a></div></div>'}
 else{
  let order=['PROPOSED','ACCEPTED','IN PROGRESS','DELIVERED','COMPLETE','DECLINED'];
  pipeHtml=order.filter(function(s){return byStage[s]}).map(function(s){
   let rows=props.filter(function(p){return propStageOf(p)===s}).map(function(p){
    let m=proposalMath(p.items,p.offered,p.selected,p.mult,p.tier);
    let other=p.dir==='SENT'?p.contact:p.artist;
    return '<div class="list-row"><div class="list-info"><strong>'+safe(p.briefTitle)+'</strong><small>'+(p.dir==='SENT'?'Sent by you':'Received')+' · with '+safe(other)+' · total '+money(m.total)+'</small><p class="prop-fee">artist keeps '+money(m.keep)+' '+FEE_LABEL+'</p></div><span class="badge">'+s+'</span><a class="mini-btn" href="#/messages">OPEN THE THREAD</a></div>'}).join('');
   return '<div class="pipe-group" data-stage="'+s+'" data-count="'+byStage[s]+'"><h3 class="pipe-head">'+s+' <span class="meta">· '+byStage[s]+' proposal'+(byStage[s]===1?'':'s')+'</span></h3>'+rows+'</div>'}).join('')}
 let standTier='<div class="step"><span class="eyebrow">Your tier</span><h3 style="margin-top:8px">'+safe(tier.name.toUpperCase())+'</h3><p>'+(tier.monthly?tier.price+'/mo — ':'Free — ')+feeLine(tier)+'. Your tier rides on your account record on this device.</p><div class="actions" style="margin-top:12px"><a class="outline" href="#/membership" style="text-decoration:none;padding:11px 16px;border-radius:12px">'+(tierName==='Viper Vanguard'?'SEE MEMBERSHIP':'UPGRADE')+' →</a></div></div>';
 let standFnd=fnd
  ?'<div class="step"><span class="eyebrow">Founding 100</span><h3 style="margin-top:8px">SEAT #'+fnd.seat+' OF 100</h3><p>Application in under <b style="color:#fff">'+safe(fnd.app.name)+'</b> · '+safe(fnd.app.category)+' — your seat is counted from the applications stored on this device, never padded.</p><div class="actions" style="margin-top:12px"><a class="outline" href="#/founding100" style="text-decoration:none;padding:11px 16px;border-radius:12px">SEE THE FOUNDING 100 →</a></div></div>'
  :'<div class="step"><span class="eyebrow">Founding 100</span><h3 style="margin-top:8px">NO APPLICATION — YET</h3><p>No Founding 100 application under your name on this device. The counter only counts real applications — yours could be the next real one.</p><div class="actions" style="margin-top:12px"><a class="outline" href="#/founding100" style="text-decoration:none;padding:11px 16px;border-radius:12px">APPLY FOR A SEAT →</a></div></div>';
 let standCats='<div class="step"><span class="eyebrow">Your world</span><h3 style="margin-top:8px">YOUR CATEGORIES</h3>'+(cats.length?'<div class="chips" style="margin:10px 0">'+cats.map(function(c){return '<span class="chip">✦ '+safe(c)+'</span>'}).join('')+'</div><p>Briefs in these categories surface first on Your Board — the wall, tuned to your craft.</p>':'<p>No categories yet — list a piece in your craft, or apply to the Founding 100 under your primary category, and your world takes shape.</p>')+'<div class="actions" style="margin-top:12px"><a class="outline" href="#/account" style="text-decoration:none;padding:11px 16px;border-radius:12px">TUNE ON YOUR PROFILE →</a></div></div>';
 return `<div class="page-hero" style="--ph:#FFD166"><div class="shell"><div class="eyebrow">Artist studio · demo</div><h1 class="page-title">PROOF OF <span class="paint">SELLING.</span></h1><p class="sub">Counted live from the records this browser holds — your listings, your proposals, your alerts. A number that cannot be traced to a stored record is never printed in this room.</p></div></div>
<section class="section"><div class="shell">
<div class="panel studio-move" data-move="${move.key}"><div class="eyebrow" style="color:var(--gold)">✦ Your next best move</div><h2 style="font-size:30px;margin:8px 0">${move.title}</h2><p class="sub" style="margin-bottom:14px">${move.body}</p><a class="primary" href="${move.href}" style="text-decoration:none;display:inline-flex;align-items:center">${move.cta}</a></div>
<div class="section-top" style="margin-top:38px"><div><div class="eyebrow">Counted, not claimed</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">MY <span class="paint">NUMBERS.</span></h2></div></div>
<div class="studio-stats">${stats}</div>
<div class="section-top" style="margin-top:30px"><div><div class="eyebrow">On your shelves</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">MY <span class="paint">LISTINGS.</span></h2></div><a class="primary" href="#/sell" style="text-decoration:none">+ NEW LISTING</a></div>
<div class="panel">${listRows}</div>
<div class="section-top" style="margin-top:38px"><div><div class="eyebrow">Commissions in motion</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">MY <span class="paint">PIPELINE.</span></h2></div><a class="text-link" href="#/messages">ALL THREADS →</a></div>
<div class="panel">${pipeHtml}</div>
<div class="section-top" style="margin-top:38px"><div><div class="eyebrow">Where you stand</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">MY <span class="paint">STANDING.</span></h2></div></div>
<div class="steps">${standTier}${standFnd}${standCats}</div>
<div class="notice">Demo honesty: this studio reads only this browser’s stored records — listings, proposals, alerts, applications. The production build connects the real platform; until then, this room prints no total it cannot trace, and neither should anyone.</div>
</div></section>`}
function artists(){let names=[...new Set(all().map(a=>a.artist))];let aq=(state.artistQuery||'').toLowerCase().replace('@','');let mem=get(STORE.directory,[]).filter(m=>(m.username||'').toLowerCase().replace('@','').includes(aq)||(m.bio||'').toLowerCase().includes(aq));let memHtml=mem.map(memberCard).join('');let shown=names.filter(n=>n.toLowerCase().includes(aq)||(USERNAMES[n]||'').includes(aq)||all().some(a=>a.artist===n&&a.category.toLowerCase().includes(aq)));return `<div class="page-hero" style="--ph:#FF5C8A"><div class="shell"><div class="eyebrow">Meet the humans behind the art</div><h1 class="page-title">CREATORS WITH <span class="paint">NO LIMITS.</span></h1></div></div><section class="section"><div class="shell"><div class="filters"><input class="field" id="searchArtist" value="${safe(state.artistQuery||'')}" placeholder="Search artists by name or @username…" aria-label="Search artists"></div>${(shown.length||mem.length)?'':'<div class="empty">No artists or members match that search yet — try another name.</div>'}<div class="art-grid">${shown.map((n,i)=>`<div class="panel">${avatarMono(n,'margin-bottom:15px')}<h3>${safe(n)}</h3>${USERNAMES[n]?'<p class="meta" style="color:var(--cyan);font-weight:700">@' + USERNAMES[n] + '</p>':''}<p class="meta">Independent artist · ${all().filter(a=>a.artist===n).length} artworks</p>${RATINGS[n]?`<div style="margin-top:6px">${stars(RATINGS[n].r)} <b style="color:#fff">${RATINGS[n].r}</b> <span class="meta">(${RATINGS[n].n} reviews)</span></div><div style="margin-top:6px">${ageBadge(AGES[n])}</div>`:""}${slotsChip(n)?'<div style="margin-top:8px">'+slotsChip(n)+'</div>':''}<div class="actions"><button class="outline" data-action="contact" data-artist="${safe(n)}">MESSAGE ARTIST ✉</button>${followBtn(n)}<button class="outline" data-action="share-artist" data-artist="${safe(n)}">SHARE CARD ↗</button></div></div>`).join('')}${memHtml}</div></div></section>`}
function flower(){return `<div class="carpet-hero"><div class="shell" style="display:flex;gap:34px;align-items:center;flex-wrap:wrap"><div style="flex:1;min-width:290px"><div class="eyebrow" style="color:#ffd76a">✦ The Red Carpet ✦</div><h1 class="page-title carpet-name">FLOWER <span class="gold">MILLS</span></h1><p class="carpet-role">FOUNDER OF PAINTED PYTHON</p><p class="sub" style="color:#f3e3e8;max-width:520px">Artist first. Founder always. This is the name on the door of the house she built — and the carpet is rolled out.</p><div class="actions"><a class="primary" href="#/creator" style="text-decoration:none">READ HER STORY ↗</a><a class="outline" href="#/explore" style="text-decoration:none;display:inline-flex;align-items:center">SEE WHAT SHE BUILT →</a></div></div><div class="carpet-frame"><img class="carpet-crown" src="assets/flower-painty-crown.png" alt="Painty the rainbow python in royal form, wearing her gold number one crown — artwork by Flower Mills"><img class="carpet-photo" src="assets/flower-portrait.jpg" alt="Flower Mills, founder of Painted Python — golden-hour portrait"></div></div></div><div class="carpet-strip"></div><section class="section" style="padding-bottom:0"><div class="shell"><div class="panel lineage-panel"><div class="eyebrow" style="color:#ffd76a">The Lineage</div><h2 class="section-title" style="font-size:clamp(32px,4.6vw,54px)">SHE COMES FROM <span class="gold">BEASTS.</span></h2><p style="line-height:1.8;max-width:760px">Flower Mills is the daughter of <a class="carpet-link" href="https://163faith.com" target="_blank" rel="noopener"><b>Pastor Jeremy Chico Mills</b></a> — successful entrepreneur and pastor; a man who builds companies and leads a congregation. The name behind hers carries weight, and he lends it to her launch on purpose: his church and business audiences are her first crowd, and her rising name carries his right back.</p><p style="line-height:1.8;max-width:760px;margin-top:12px">Legacy is not a handout in this family. It is a starting line — and she is already running.</p></div></div></section><section class="section"><div class="shell"><div class="section-top"><div><div class="eyebrow">The first works of the house</div><h2 class="section-title">THE OPENING <span class="paint">GALLERY.</span></h2></div><p class="meta" style="max-width:340px">Before there was a marketplace, there was her hand. These are the pieces Painted Python opened with — chosen by her, credited to her, hers forever.</p></div><div class="art-grid carpet-gallery"><div class="panel" style="text-align:center"><img src="assets/flower-join-now.png" alt="Rainbow python artwork by Flower Mills holding a Join Now sign" style="width:100%;max-width:430px;display:block;margin:0 auto;filter:drop-shadow(0 18px 28px rgba(0,0,0,.55))"><h3 style="font-family:Cinzel,serif;letter-spacing:1px;margin-top:16px">“JOIN NOW!” — PIECE #1</h3><p class="sub" style="margin:8px auto 0">Painty, the rainbow python, holding the door open for every artist who follows. The first artwork ever placed on Painted Python.</p><p class="meta" style="margin-top:10px">Original artwork by <b style="color:#fff">Flower Mills</b> · signed LilFlower37</p></div><div class="panel" style="text-align:center"><img src="assets/flower-painty-crown.png" alt="Painty the rainbow python wearing a gold number one crown, by Flower Mills" style="width:100%;max-width:430px;display:block;margin:0 auto;filter:drop-shadow(0 18px 28px rgba(0,0,0,.55))"><h3 style="font-family:Cinzel,serif;letter-spacing:1px;margin-top:16px">“AWESSSSOME!!” — PAINTY, CROWNED #1</h3><p class="sub" style="margin:8px auto 0">Painty in royal form — rainbow scales, magenta eyes, the gold crown of the house. The same royal who holds court at the head of the Top Sellers board.</p><p class="meta" style="margin-top:10px">Original artwork by <b style="color:#fff">Flower Mills</b> · Piece #2</p></div></div></div></section><section class="section alt" style="padding-top:56px"><div class="shell"><div class="eyebrow">The road so far</div><h2 class="section-title">JUST THE <span class="paint">BEGINNING.</span></h2><div class="steps carpet-steps" style="margin-top:26px"><div class="step"><span class="chip">OCT 23, 2026</span><h4 style="margin-top:14px">A NAME GETS A HOME</h4><p>paintedpython.com is bought. The carpet starts here.</p></div><div class="step"><span class="chip">OCT 24, 2026</span><h4 style="margin-top:14px">THE DOORS OPEN</h4><p>Painted Python goes live to the world.</p></div><div class="step"><span class="chip">OCT 24, 2026</span><h4 style="margin-top:14px">THE FOUNDER WALKS IN</h4><p>Flower joins her own marketplace as @PrincessFlower.</p></div><div class="step"><span class="chip">OCT 25, 2026</span><h4 style="margin-top:14px">THE BOARD OPENS</h4><p>The Commission Board goes live — buyers post briefs, artists pitch. The beating heart starts beating.</p></div></div><p class="meta" style="margin-top:16px">The road so far — and it is just beginning. New milestones get carved on this wall as they land.</p></div></section><section class="section"><div class="shell"><div class="eyebrow">Walk her world</div><h2 class="section-title">THE <span class="paint">DOORS.</span></h2><div class="steps" style="margin-top:26px"><div class="step"><h3>HER STORY, HER WORDS</h3><p>The About Flower page carries her bio exactly as she wrote it — untouched, unedited, hers.</p><div class="actions" style="margin-top:14px"><a class="outline" href="#/creator" style="text-decoration:none">ABOUT FLOWER →</a></div></div><div class="step"><h3>@PRINCESSFLOWER</h3><p>Her own account on her own marketplace. She did not just build the house — she moved in.</p><div class="actions" style="margin-top:14px"><a class="outline" href="#/account" style="text-decoration:none">HER STAGE →</a></div></div><div class="step"><h3>SEE WHAT SHE BUILT</h3><p>Walk the marketplace she made: explore the art, meet the artists, stand at the board where buyers post their dreams.</p><div class="actions" style="margin-top:14px"><a class="outline" href="#/explore" style="text-decoration:none">EXPLORE →</a><a class="outline" href="#/board" style="text-decoration:none">THE BOARD →</a></div></div><div class="step"><h3>MEET THE CO-FOUNDERS</h3><p>She did not build this house alone. Meet the operator standing beside the artist — the two names on the door.</p><div class="actions" style="margin-top:14px"><a class="outline" href="#/founders" style="text-decoration:none">MEET THE CO-FOUNDERS →</a></div></div></div></div></section>`}
/* CO-FOUNDERS (owner ruling, 2026-10-30) — the two people behind the house:
   the artist who founded it and the operator who runs it. Factual only. */
function founders(){return `<div class="page-hero founders-hero"><div class="shell"><div class="eyebrow">✦ The people behind the python</div><h1 class="page-title">CO-FOUNDERS</h1><p class="sub">One artist who started it. One operator who runs it. Painted Python is a family-built house for independent artists.</p></div></div><section class="section"><div class="shell"><div class="founders-grid"><div class="panel founder-card"><img class="founder-photo" src="assets/jeremy-mills.webp" alt="Jeremy Chico Mills, Co-Founder and CEO of Painted Python"><h3>Jeremy Chico Mills</h3><p class="founder-role">Co-Founder &amp; CEO</p><p>The operator — he runs the business, the money, and the machine behind the marketplace so artists can just make art.</p></div><div class="panel founder-card"><img class="founder-photo" src="assets/flower-portrait.jpg" alt="Flower Mills, Co-Founder of Painted Python"><h3>Flower Mills</h3><p class="founder-role">Co-Founder</p><p>The artist who started it — creator of Painty and the original vision for a human-made art home.</p><div class="actions" style="margin-top:16px"><a class="outline" href="#/creator" style="text-decoration:none">ABOUT FLOWER →</a><a class="outline" href="#/flower" style="text-decoration:none">THE RED CARPET →</a></div></div></div></div></section>`}
/* ABOUT FLOWER — the bio rendered by creator() below was supplied verbatim by
   Flower on 2026-10-24 and long carried a standing "do not edit her words"
   note. Per the owner's direct ruling of 2026-10-30 (Jeremy Mills,
   full-operation takeover), ONLY the opening sentence's descriptor phrase
   ("Christian, queer, autistic") was removed; every other word of her bio
   remains exactly as she wrote it. */
function creator(){return `<div class="page-hero" style="--ph:#FF5C8A"><div class="shell"><div class="eyebrow">The human behind the python</div><h1 class="page-title"><span class="paint">About Flower</span></h1><p class="sub">Painted Python was created by an artist, for artists.</p></div></div><section class="section"><div class="shell two-col"><div><h2 class="section-title">FLOWER <span class="paint">MILLS</span></h2><p class="sub" style="margin-bottom:14px">Creator &amp; Founder of Painted Python · Digital artist</p><p style="line-height:1.75;margin-bottom:14px">Flower Mills is a digital artist who dips her creativity into many things — and built Painted Python because artists deserved a home that treats them like the main event. No faceless listings. No fee games. A place where you can message the artist, ask about the piece, and own something personal.</p><p style="line-height:1.75;margin-bottom:14px">Her pricing philosophy runs the whole company: keep fees low, show the math plainly, and let artists keep what they earn. Hatchling is free forever because she insisted on it.</p><p style="line-height:1.75">Her own studio — <b>Flower Mills</b> — is Shop #1 on Painted Python, and her first piece is already home: Painty, the rainbow python watching over the front page.</p><p style="line-height:1.75;margin-bottom:14px">Flower is an artist with a lifelong passion for creativity and imagination. From a young age, she discovered her love for drawing, which eventually blossomed into a journey of self-taught artistry and imaginative creation.</p><p style="line-height:1.75;margin-bottom:14px">Alongside her passion for art, Flower developed a deep appreciation for reptiles, particularly snakes. Inspired by their vibrant colors, unique beauty, and often misunderstood nature, she hopes to challenge negative perceptions of snakes by celebrating them through art and creativity.</p><p style="line-height:1.75;margin-bottom:14px">Combining these passions, Flower created a snake-themed website dedicated to supporting artists and independent creators. Her mission is to provide a space where talented individuals can showcase their work, share their creativity, and earn money through their artistic abilities.</p><p style="line-height:1.75;margin-bottom:14px">Flower believes that art is a powerful kind of magic—one that deserves to be nurtured, shared, and celebrated. Through her platform, she hopes to empower fellow artists to embrace their talents, pursue their passions, and turn their imagination into something truly special.</p><div class="row" style="display:flex;gap:10px;margin-top:20px"><a class="primary" href="#/artists" style="text-decoration:none;padding:12px 18px;border-radius:12px">VISIT HER STUDIO ↗</a><a class="outline" href="#/membership" style="text-decoration:none;padding:12px 18px;border-radius:12px">SEE HOW SHE PRICED IT</a><a class=\"outline\" href=\"#/flower\" style=\"text-decoration:none;padding:12px 18px;border-radius:12px\">VISIT HER RED CARPET ✦</a></div></div><aside><div class="panel" style="padding:12px;margin-bottom:16px"><img src="assets/flower-portrait.jpg" alt="Flower Mills, Creator and Founder of Painted Python" style="width:100%;display:block;border-radius:12px;aspect-ratio:4/4.6;object-fit:cover;object-position:center 22%"><p class="meta" style="margin-top:10px"><b style="color:#fff">Flower Mills</b> — Creator &amp; Founder of Painted Python. The artist behind the marketplace, and Shop #1.</p></div><div class="artist-spot"><img src="assets/flower-portrait.jpg" alt="Flower Mills" style="width:64px;height:64px;border-radius:50%;object-fit:cover;object-position:center 22%;flex:none"><div><h3>FLOWER MILLS</h3><p class="sub">Creator of Painted Python · Studio #1 · Founding artist — her real artwork becomes part of this site's design, chosen by her, credited to her, hers forever.</p></div></div><div class="panel" style="padding:14px;margin-top:16px"><img src="assets/flower-join-now.png" alt="Rainbow python artwork by Flower Mills holding a Join Now sign" style="width:100%;display:block;filter:drop-shadow(0 14px 22px rgba(0,0,0,.55))"><p class="meta" style="margin-top:10px">“Join Now!” — that's <b style="color:#fff">Painty</b>, the Painted Python herself. Her first piece on the site — drawn by Flower, signed LilFlower37.</p></div></aside></div></section>`}
function noTrapPromise(){return `<div class="promise-bar"><span class="promise-mark">✦ THE NO-TRAP PROMISE</span><p>Join in a tap. <b>Cancel in two taps</b> — from your account, any time. No emails, no phone calls, no guilt trips. Stated up front, because that is where a promise belongs.</p></div>`}
function etsyComparePanel(){return `<div class="panel etsy-panel"><div class="eyebrow">Why not Etsy</div><h3 style="margin-bottom:8px">RUN A $200 SALE THROUGH BOTH STACKS.</h3><p class="sub" style="margin-bottom:14px">One honest fee, or a stack of separate ones. These are the published components on their side and the whole story on ours — the math does the talking.</p><div class="stack-cols"><div class="stack-col"><h4>ETSY — FEE BY FEE</h4><ul><li><b>6.5% transaction fee</b> on every sale</li><li><b>Payment processing</b> charged on every order</li><li><b>A listing fee</b> for every item you post</li><li><b>Offsite Ads fees</b> where they apply, on top of the rest</li></ul><p class="meta">Separate fees, each leaving the artist’s pocket on its own schedule.</p></div><div class="stack-col ours"><h4>PAINTED PYTHON — ONE FEE</h4><ul><li><b>One platform fee:</b> 8% / 5% / 3% by tier — nothing stacked on it</li><li>You keep <b>$184 / $190 / $194</b> on a $200 sale, after platform fee</li><li>Processing shown at checkout, before it costs you anything</li><li>No listing fees — and no ad program you are forced to buy</li></ul><p class="meta">The founder set these fees low on purpose, and printed them where everyone can read them.</p></div></div></div>`}
function membership(){return `<div class="page-hero grotto-hero"><div class="shell"><div class="eyebrow">Grow on your own terms</div><h1 class="page-title">CLAIM YOUR <span class="paint">CREATIVE SPACE.</span></h1><p class="sub">Artist tiers locked by the founder (2026-10-23). Collectors: The Serpent Circle — $7.99/mo for early drops, first commission slots, and the collection vault.</p></div></div><section class="section"><div class="shell">${noTrapPromise()}<div class="membership">${TIER_DATA.map(t=>tierCard(t,true)).join('')}</div><p class="meta" style="margin:14px 0 0">Every keep figure on this page is after platform fee · processing shown at checkout — no surprises, ever.</p><div class="panel compare-panel"><div class="eyebrow">Side by side</div><h3 style="margin-bottom:10px">THE SAME HOUSE, THREE DOORS.</h3>${compareTable()}<p class="meta" style="margin-top:10px">Fees are the founder’s, locked 2026-10-23. Monthly billing only — Painted Python sells no annual plan, so nobody can sell you one in our name.</p></div><div class="panel" style="margin:20px 0 0;border:2px solid #7a3cff"><div class="eyebrow">✦ The Founding 100</div><h3 style="margin-bottom:6px">FOUNDING ARTISTS LOCK PYTHON AT $6/MO — FOR 24 MONTHS.</h3><p class="sub" style="margin-bottom:12px">The first 100 artists to build this house keep Python at $6/month locked for two years (standard $9.99), wear the Founding Python badge forever, and save $95.76 across the lock. The cohort opens with the production launch — applications in this demo are stored on your device.</p><a class="primary" href="#/founding100" style="text-decoration:none;display:inline-flex;align-items:center">SEE THE FOUNDING 100 →</a></div></div></section><section class="section alt"><div class="shell two-col" style="align-items:start"><div><div class="eyebrow">✦ For collectors</div><h2 class="section-title">THE SERPENT <span class="paint">CIRCLE.</span></h2><p class="sub" style="margin-bottom:12px">For the collectors who want to be in the room before the door opens. The Circle is how you collect first, commission first, and keep everything you gather in one beautiful room.</p><p class="sub" style="margin-bottom:16px">Buying and messaging stay <b style="color:#fff">free for everyone, always</b> — the Circle never sells the basics. It sells first looks.</p><div class="amount" style="font-size:42px;font-weight:900">$7.99<span style="font-size:14px;font-weight:500;color:var(--muted)"> / month</span></div><div class="actions" style="margin-top:14px"><button class="primary" data-action="tier" data-tier="The Serpent Circle">JOIN THE CIRCLE ↗</button></div><p class="meta" style="margin-top:10px">Cancel in two taps — the same promise as every tier in this house.</p></div><div class="panel circle-panel"><div class="eyebrow">What the Circle holds</div><ul class="circle-list"><li><b>Early drop access</b><span>Circle collectors walk into every drop before the public line forms.</span><em class="launch-tag">Arrives with launch</em></li><li><b>First shot at commission slots</b><span>When an artist opens commission slots, the Circle is asked first — before the slot ever reaches the wall.</span><em class="launch-tag">Arrives with launch</em></li><li><b>The Collection Vault</b><span>Every piece you collect, gathered in one room with its artist and its story — your collection, telling its story back to you.</span><em class="launch-tag">Opens with launch</em><a class="text-link" href="#/saved">YOUR SAVED PIECES LIVE HERE TODAY →</a></li></ul><p class="meta" style="margin-top:6px">The vault opens with the production launch. Until then, everything you save waits for you under Saved — nothing is lost, nothing is promised early.</p></div></div></section><section class="section"><div class="shell">${etsyComparePanel()}<div class="notice">Demo only — no subscription, payment, or purchase can be completed here. Prices shown are the founder-approved tiers; billing activates with the production build. Keep figures are after platform fee — processing shown at checkout — no surprises, ever.</div></div></section>`}
function messages(){let inbox=get(STORE.messages,{});let contacts=[...new Set([...all().map(a=>a.artist),...Object.keys(inbox)])];if(!contacts.includes(state.chatTo))state.chatTo=contacts[0]||'Artist';let msgs=inbox[state.chatTo]||[];let propNow=latestProposal(state.chatTo);let propZone='<div class="prop-zone">'+(propNow?proposalCard(propNow):'')+proposalBuilder(!!propNow)+'</div>';return `<div class="page-hero" style="--ph:#39D0C4"><div class="shell"><div class="eyebrow">Art starts the conversation</div><h1 class="page-title">TALK TO THE <span class="paint">CREATOR.</span></h1><p class="sub">Local demonstration inbox. Messages are stored only in your browser and are not delivered to real artists.</p></div></div><section class="section"><div class="shell"><div class="chat-layout"><aside class="chat-list"><p class="eyebrow">ARTIST CONVERSATIONS</p>${contacts.map(n=>`<button class="chat-contact ${n===state.chatTo?'active':''}" data-action="chat" data-artist="${safe(n)}">◉ &nbsp; ${safe(n)}</button>`).join('')}</aside><div class="chat-main"><div style="padding:19px;border-bottom:1px solid #43364f;font-weight:900">✉ ${safe(state.chatTo)} <small class="meta"> · DEMO CHAT</small></div>${propZone}<div class="chat-history">${msgs.length?msgs.map(m=>`<div class="bubble mine">${safe(m.text)}</div>`).join(''):'<div class="empty">Start a conversation about an artwork, a commission, or the creative process.</div>'}</div><form id="chatForm" class="chat-compose"><input class="field" name="text" placeholder="Ask about artwork or a commission…" required maxlength="1000"><button class="primary" type="submit">SEND ↗</button></form></div></div></div></section>`}
function basket(){let ids=cart(),items=ids.map(id=>all().find(a=>a.id===id)).filter(Boolean);return `<div class="page-hero" style="--ph:#FFB84D"><div class="shell"><div class="eyebrow">Your next discoveries</div><h1 class="page-title">YOUR <span class="paint">CART.</span></h1></div></div><section class="section"><div class="shell checkout-rows"><div class="panel">${items.length?items.map(a=>`<div class="list-row"><div class="list-thumb" style="${artLook(a)}">${a.img?'<img src="'+safe(a.img)+'" alt="">':'◉'}</div><div class="list-info"><strong>${safe(a.title)}</strong><small>${safe(a.artist)} · ${money(a.price)}</small></div><button class="mini-btn" data-action="remove" data-id="${a.id}">REMOVE</button></div>`).join(''):'<div class="empty">Your cart is ready for a little creative chaos. <a href="#/explore" class="text-link">Discover art →</a></div>'}</div>${items.length?`<div class="checkout-total"><span>Estimated subtotal</span><span>${money(items.reduce((s,a)=>s+a.price,0))}</span></div><div class="notice">Shipping, taxes, stock verification, fees, and real payment processing are not implemented.</div><button class="primary" data-action="checkout">CHECKOUT DEMO ↗</button>`:''}</div></section>`}
function notFound(){return `<section class="section"><div class="shell"><h1 class="page-title">NOT FOUND.</h1><a href="#/" class="primary">BACK TO SLITHER</a></div></section>`}

const RATINGS={'Nova Reyes':{r:4.9,n:47},'Sam Rivera':{r:4.9,n:38},'River Quinn':{r:4.8,n:41},'Kai Santos':{r:4.8,n:29},'Ari Moon':{r:4.7,n:33},'Jules Carter':{r:4.7,n:21},'Milo Banks':{r:4.6,n:18},'Eli Morgan':{r:4.6,n:12}};
const AGES={'Nova Reyes':24,'Sam Rivera':31,'River Quinn':28,'Kai Santos':17,'Ari Moon':22,'Jules Carter':26,'Milo Banks':35,'Eli Morgan':29};
const USERNAMES={'Nova Reyes':'novareyes','Sam Rivera':'samrivera','River Quinn':'riverquinn','Kai Santos':'kaisantos','Ari Moon':'arimoon','Jules Carter':'julescarter','Milo Banks':'milobanks','Eli Morgan':'elimorgan'};
function ageBadge(age,big){if(age===null||age===undefined||isNaN(age))return '';let extra=big?'font-size:13px;padding:7px 13px;':'';if(age<18)return '<span class="badge" style="background:#14507a;color:#bfe3ff;'+extra+'">🛡 MINOR · 13–17</span>';return '<span class="badge" style="background:#3a3f4a;color:#e6ebf2;'+extra+'">🛡 ADULT · 18+</span>'}
const REVIEWS={'Nova Reyes':[{q:'She messaged me back within the hour and sent progress photos the whole way. The portrait made my sister cry — in the good way.',b:'Maya R.',w:'Custom portrait'},{q:'Colors are even richer in person. Packed like it was glass and gold.',b:'Dev P.',w:'Original painting'}],'Sam Rivera':[{q:'I asked for a desert piece for my studio and he asked about my light before painting. Who does that? It is perfect.',b:'Jordan T.',w:'Original painting'},{q:'Second piece I have bought from Sam. Zero drama, all heart.',b:'Priya K.',w:'Original painting'}],'River Quinn':[{q:'My commission was a weird idea and River treated it like it mattered. It did. It does.',b:'Alex M.',w:'Commission'}],'Kai Santos':[{q:'Fast, kind, and the detail up close is unreal.',b:'Sam W.',w:'Original artwork'}],'Ari Moon':[{q:'Bought a print, came back for the original. That is the review.',b:'Lee C.',w:'Print, then original'}],'Jules Carter':[{q:'Great communication from the first message to delivery day.',b:'Robin D.',w:'Original artwork'}],'Milo Banks':[{q:'Bold, strange, exactly as promised.',b:'Kit A.',w:'Original artwork'}],'Eli Morgan':[{q:'First art purchase ever. Eli made it easy and the piece is stunning.',b:'Jo F.',w:'Original artwork'}]};
function stars(r){let f=Math.round(r);return '<span class="stars" aria-label="'+r+' out of 5 stars">'+'★'.repeat(f)+'☆'.repeat(5-f)+'</span>'}
function topSellers(){let names=[...new Set(all().map(a=>a.artist))].filter(n=>RATINGS[n]);names.sort((a,b)=>RATINGS[b].r-RATINGS[a].r||RATINGS[b].n-RATINGS[a].n);let rtitles=['World Serpent','Titanoboa','King Cobra'];let rcolors=['#FFC94D','#D7DCE6','#E39A5F'];let podium=names.slice(0,3).map((n,i)=>{let t=RATINGS[n];let rv=(REVIEWS[n]||[])[0];return '<div class="panel" style="text-align:center;padding:26px 20px"><div class="medal-num" style="border-color:'+rcolors[i]+';color:'+rcolors[i]+'">#'+(i+1)+'</div><div style="font-family:Cinzel Decorative,serif;font-size:21px;letter-spacing:1px;color:'+rcolors[i]+';margin-top:6px">#'+(i+1)+' '+rtitles[i]+'</div>'+avatarMono(n,'margin:10px auto')+'<h3 style="font-size:22px">'+safe(n)+'</h3><div style="margin-top:6px">'+ageBadge(AGES[n])+'</div><div style="margin:6px 0">'+stars(t.r)+' <b style="color:#fff">'+t.r+'</b></div><p class="meta">'+t.n+' customer reviews</p>'+(rv?'<p style="line-height:1.65;font-style:italic;margin-top:12px">“'+safe(rv.q)+'”</p><p class="meta">— '+safe(rv.b)+' · '+safe(rv.w)+'</p>':'')+'<div class="actions" style="justify-content:center"><button class="outline" data-action="contact" data-artist="'+safe(n)+'">MESSAGE ARTIST ✉</button></div></div>'}).join('');let rows=names.slice(3).map((n,i)=>{let t=RATINGS[n];let rv=(REVIEWS[n]||[])[0];return '<div class="panel" style="display:flex;gap:16px;align-items:flex-start;margin-bottom:12px"><div style="font-size:22px;font-weight:900;color:#fff;min-width:34px">#'+(i+4)+'</div><div style="flex:1"><h3>'+safe(n)+' '+ageBadge(AGES[n])+'</h3><div style="margin:4px 0">'+stars(t.r)+' <b style="color:#fff">'+t.r+'</b> <span class="meta">· '+t.n+' reviews</span></div>'+(rv?'<p style="line-height:1.6;font-style:italic">“'+safe(rv.q)+'”</p><p class="meta">— '+safe(rv.b)+' · '+safe(rv.w)+'</p>':'')+'</div><button class="outline" data-action="contact" data-artist="'+safe(n)+'">MESSAGE ✉</button></div>'}).join('');return '<div class="page-hero" style="--ph:#FFD166"><div class="shell" style="display:flex;gap:26px;align-items:center;flex-wrap:wrap"><div style="flex:1;min-width:270px"><div class="eyebrow">Rated by the people who bought the art</div><h1 class="page-title">TOP <span class="paint">SELLERS.</span></h1><p class="sub">The highest-rated artists on Painted Python, ranked by the customers who actually bought from them. Every rating comes from a completed order — no bought stars, no fake love. The top three hold serpent titles — World Serpent, Titanoboa, King Cobra — earned, never given.</p></div><img src="assets/flower-painty-crown.png" alt="Painty the rainbow python wearing a gold number one crown, by Flower Mills" style="width:min(290px,78vw);display:block;filter:drop-shadow(0 18px 28px rgba(0,0,0,.55))"></div></div><section class="section" style="padding-top:26px"><div class="shell"><div class="art-grid" style="margin-bottom:26px">'+podium+'</div>'+rows+'<div class="panel" style="margin-top:22px"><h3>How ratings work</h3><div class="steps" style="margin-top:12px"><div class="step"><b>1</b><h4>Order completes</h4><p>Only customers whose order was delivered can rate the artist — 1 to 5 stars, plus a written review.</p></div><div class="step"><b>2</b><h4>Reviews stay honest</h4><p>Reviews live on the artist’s record permanently. Artists can reply, but never edit or delete what a customer said.</p></div><div class="step"><b>3</b><h4>The board ranks itself</h4><p>Top Sellers sorts by average rating, with review count breaking ties. Care for your customers and the board notices.</p></div></div><p class="meta" style="margin-top:14px">Preview board: ratings and reviews go live with real orders at launch — the artists and reviews shown here demonstrate exactly how the board will look and work.</p></div></div></section>'}

const CATEGORIES=['Painting','Digital Art','Illustration','Drawing & Sketch','Photography','Sculpture','Mixed Media','Collage','Printmaking','Prints & Posters','Ceramics','Textile & Fiber Art','Glass Art','Wood Art','Metal Art','Resin Art','Paper Art','Calligraphy & Lettering','Street Art & Murals','Tattoo Flash','Custom Portraits','Pet Portraits','Anime & Manga Style','3D & CGI Art','Cosplay','Pottery','Character Design','Commissions','Outfit Design'];
const BRIEF_SEED=[
{id:'ex1',title:"A portrait of my sister, mid-laugh",buyer:'Maya R.',category:'Custom Portraits',budget:300,timeline:'By early December — it is a birthday gift',details:"My sister never sits still, so this would be painted from photos I will share in our thread. I want the joy to be the whole point — bright, warm, unmistakably her.",pitches:3},
{id:'ex2',title:'A desert night piece for my studio wall',buyer:'Jordan T.',category:'Painting',budget:450,timeline:'Within a month',details:"One large canvas for the wall behind my desk. Saguaro silhouettes, a huge moon, deep blues. I will send photos of the room and the light so it fits the space.",pitches:5},
{id:'ex3',title:'My senior dog, dignified and slightly grumpy',buyer:'Priya K.',category:'Pet Portraits',budget:180,timeline:'No rush — when it is right',details:"Biscuit is fourteen, half-blind, and entirely convinced he owns the house. I want a portrait that keeps the grump and the sweetness in equal measure.",pitches:7},
{id:'ex4',title:'Album cover for an indie EP',buyer:'Alex M.',category:'Digital Art',budget:250,timeline:'Three weeks',details:"Five songs about leaving a small town. I need cover art that feels like a bus window at dawn — hopeful, a little lonely. Square format, text-free so I can add the title.",pitches:4},
{id:'ex5',title:'A flash sheet of moths and moons',buyer:'Lee C.',category:'Tattoo Flash',budget:150,timeline:'Within a month',details:"Six to eight designs: death's-head moths, crescent moons, tiny stars. Clean lines, black ink, palm-sized. It is my first flash sheet request — be kind and be bold.",pitches:2},
{id:'ex6',title:'Four mugs that feel like river stones',buyer:'Robin D.',category:'Ceramics',budget:220,timeline:'1–3 months',details:"A set of four handmade mugs, smooth and weighty like stones from a riverbed. Earth tones, no two exactly alike. They are a gift for my sister's coffee ritual.",pitches:1},
{id:'ex7',title:'A mural for a community garden fence',buyer:'Kit A.',category:'Street Art & Murals',budget:900,timeline:'Spring, weather permitting',details:"Thirty feet of fence at our neighborhood garden. Vegetables, bees, and one enormous sunflower. The garden committee pays — I am the messenger and the tomato grower.",pitches:6},
{id:'ex8',title:'Spot illustrations for a children’s poem book',buyer:'Jo F.',category:'Illustration',budget:600,timeline:'Two months',details:"Twelve small spot illustrations for a book of gentle poems — a fox, a kettle, a very small boat. Whimsical but never saccharine. I will share the poems in our thread.",pitches:0}
];
function briefPitches(b){if(b.mine)return b.pitches||0;return (b.pitches||0)+(get(STORE.pitchbonus,{})[b.id]||0)}
function allBriefs(){return [...get(STORE.briefs,[]),...BRIEF_SEED]}
function openThread(name){let box=get(STORE.messages,{});if(!box[name]){box[name]=[];set(STORE.messages,box)}state.chatTo=name}
function pitchBrief(bid,buyer){let bonus=get(STORE.pitchbonus,{});bonus[bid]=(bonus[bid]||0)+1;set(STORE.pitchbonus,bonus);state.propBriefId=bid;state.propDraft=null;let pb=allBriefs().find(b=>String(b.id)===String(bid));if(pb&&pb.mine)addAlert('pitch','📋 A pitch landed on your brief “'+pb.title+'” — the thread waits in your Messages.','#/messages');openThread(buyer)}
const TIER_FEES=Object.fromEntries(TIER_DATA.map(t=>[t.name,t.fee]));
const FEE_LABEL='after platform fee · processing shown at checkout';
function currentArtistTier(){let su=get(STORE.signup,{});return (su&&TIER_FEES[su.tier]!=null)?su.tier:'Hatchling'}
function proposalMath(items,offered,selected,mult,tier){let base=(items||[]).reduce((s,i)=>s+(Number(i.price)||0),0);let sel=selected||{};let off=offered||{};let m=Number(mult)||2;let rush=(off.rush&&sel.rush)?base:0;let privacy=(off.privacy&&sel.privacy)?Math.round(base*50)/100:0;let commercial=(off.commercial&&sel.commercial)?Math.round(base*(m-1)*100)/100:0;let total=Math.round((base+rush+privacy+commercial)*100)/100;let rate=TIER_FEES[tier]!=null?TIER_FEES[tier]:8;let fee=Math.round(total*rate)/100;let keep=Math.round((total-fee)*100)/100;return{base:base,rush:rush,privacy:privacy,commercial:commercial,total:total,rate:rate,fee:fee,keep:keep,mult:m}}
function getProposals(contact){let allP=get(STORE.proposals,{});return allP[contact]||[]}
function latestProposal(contact){let l=getProposals(contact);return l.length?l[l.length-1]:null}
function saveProposal(p){let allP=get(STORE.proposals,{});let l=allP[p.contact]||[];let ix=l.findIndex(x=>x.id===p.id);if(ix>=0)l[ix]=p;else l.push(p);allP[p.contact]=l;set(STORE.proposals,allP)}
function allProposalsFlat(){let allP=get(STORE.proposals,{});let out=[];Object.keys(allP).forEach(k=>{(allP[k]||[]).forEach(p=>out.push(p))});return out}
const STAGES=['PROPOSED','ACCEPTED','IN PROGRESS','DELIVERED','COMPLETE'];
function stageRail(p){if(!p)return '';if(p.status==='DECLINED')return '<div class="stage-rail"><span class="stage closed">✕ DECLINED — COMMISSION CLOSED</span></div>';let cur=p.status==='COUNTERED'?'PROPOSED':p.stage;let ix=STAGES.indexOf(cur);return '<div class="stage-rail" aria-label="Commission stage">'+STAGES.map((s,i)=>'<span class="stage '+(i<ix?'done':i===ix?'now':'')+'">'+(i<ix?'✓ ':'')+s+'</span>'+(i<STAGES.length-1?'<span class="stage-arrow">→</span>':'')).join('')+'</div>'}
const SLOT_SEED={'Nova Reyes':{total:4,used:2},'Sam Rivera':{total:5,used:4},'River Quinn':{total:3,used:1},'Kai Santos':{total:4,used:3},'Ari Moon':{total:4,used:1},'Jules Carter':{total:3,used:2},'Milo Banks':{total:5,used:2},'Eli Morgan':{total:3,used:0}};
function slotsFor(name){let seed=SLOT_SEED[name];if(!seed)return null;let accepted=allProposalsFlat().filter(p=>p.artist===name&&['ACCEPTED','IN PROGRESS','DELIVERED','COMPLETE'].indexOf(p.stage)>=0).length;let used=Math.min(seed.total,seed.used+accepted);return{total:seed.total,used:used,open:seed.total-used}}
function slotsChip(name){let s=slotsFor(name);if(!s)return '';if(s.open>0)return '<span class="chip slots-chip">✦ '+s.open+' of '+s.total+' commission slots open</span>';return '<span class="chip slots-chip full">✦ Queue full — waitlist open</span>'}
function propDraft(){if(!state.propDraft)state.propDraft={labels:['',''],prices:['',''],days:14,revisions:2,revNote:'',briefId:state.propBriefId||'',rush:true,privacy:true,commercial:true,mult:'2.5',artist:''};if(state.propBriefId&&!state.propDraft.briefId)state.propDraft.briefId=state.propBriefId;return state.propDraft}
function harvestPropDraft(){let d=propDraft();let labels=document.querySelectorAll('[data-prop-label]');if(labels&&labels.length){d.labels=[];d.prices=[];labels.forEach(function(el){d.labels.push(el.value||'')});document.querySelectorAll('[data-prop-price]').forEach(function(el){d.prices.push(el.value||'')})}let g=function(id){let el=document.getElementById(id);return el?el.value:null};let v;if((v=g('pArtist'))!==null&&v!==undefined)d.artist=v;if((v=g('pBrief'))!==null&&v!==undefined)d.briefId=v;if((v=g('pDays'))!==null&&v!==undefined)d.days=v;if((v=g('pRevisions'))!==null&&v!==undefined)d.revisions=v;if((v=g('pRevNote'))!==null&&v!==undefined)d.revNote=v;if((v=g('pMult'))!==null&&v!==undefined)d.mult=v;let c=function(id){let el=document.getElementById(id);return el?!!el.checked:null};let cv;if((cv=c('pRush'))!==null)d.rush=cv;if((cv=c('pPrivacy'))!==null)d.privacy=cv;if((cv=c('pCommercial'))!==null)d.commercial=cv;return d}
function proposalCard(p){if(!p)return '';let m=proposalMath(p.items,p.offered,p.selected,p.mult,p.tier);let locked=['ACCEPTED','IN PROGRESS','DELIVERED','COMPLETE'].indexOf(p.stage)>=0;let closed=p.status==='DECLINED';let addonRow=function(kind,label,amt,note){if(!p.offered[kind])return '';let on=!!p.selected[kind];return '<div class="prop-addon"><div><b>'+label+'</b> <span class="meta">'+note+'</span></div><div class="prop-addon-r"><b>'+(amt?money(amt):'—')+'</b>'+(locked||closed?'':'<button class="mini-btn" data-action="prop-addon" data-kind="'+kind+'" data-id="'+p.id+'">'+(on?'✓ ADDED':'ADD +')+'</button>')+'</div></div>'};let advance='';if(p.stage==='ACCEPTED')advance='<button class="primary" data-action="prop-advance" data-id="'+p.id+'">START WORK →</button>';else if(p.stage==='IN PROGRESS')advance='<button class="primary" data-action="prop-advance" data-id="'+p.id+'">MARK DELIVERED →</button>';else if(p.stage==='DELIVERED')advance='<button class="primary" data-action="prop-advance" data-id="'+p.id+'">CONFIRM COMPLETE ✓</button>';else if(p.stage==='COMPLETE')advance='<span class="meta">✓ Commission complete — delivered and confirmed (demo).</span>';return '<div class="proposal-card"><div class="prop-head"><b>📋 COMMISSION PROPOSAL</b><span class="badge '+(closed?'prop-closed-badge':'')+'">'+safe(p.status)+'</span></div>'+stageRail(p)+'<p class="meta" style="margin:8px 0">For: <b style="color:#fff">'+safe(p.briefTitle)+'</b> · Artist: <b style="color:#fff">'+safe(p.artist)+'</b> · Demo proposal — no payment moves here.</p><div class="prop-items">'+p.items.map(i=>'<div class="prop-item"><span>'+safe(i.label)+'</span><b>'+money(i.price)+'</b></div>').join('')+'<div class="prop-item subtotal"><span>Base</span><b>'+money(m.base)+'</b></div></div>'+addonRow('rush','✦ RUSH',m.rush,'+100% of base — jumps the queue')+addonRow('privacy','🔒 PRIVACY',m.privacy,'+50% of base — never posted publicly')+addonRow('commercial','💼 COMMERCIAL USE',m.commercial,'×'+m.mult+' of base (license uplift shown)')+'<div class="prop-total"><span>TOTAL</span><b>'+money(m.total)+'</b></div><p class="prop-fee">Platform fee '+m.rate+'% ('+safe(p.tier)+'): '+money(m.fee)+' — artist keeps '+money(m.keep)+' '+FEE_LABEL+'</p><p class="meta">⏱ Delivery estimate: '+p.days+' days · 🔁 Revisions: '+p.revisions+' round'+(Number(p.revisions)===1?'':'s')+(p.revNote?' — '+safe(p.revNote):'')+'</p>'+(closed?'<p class="meta">This proposal was declined — the thread stays open for a kinder idea.</p>':locked?'<div class="actions" style="margin-top:10px">'+advance+'</div>':'<div class="actions" style="margin-top:10px"><button class="primary" data-action="prop-accept" data-id="'+p.id+'">ACCEPT ✓</button><button class="outline" data-action="prop-counter" data-id="'+p.id+'">COUNTER — REPLY IN THREAD</button><button class="outline" data-action="prop-decline" data-id="'+p.id+'">DECLINE</button></div>')+'</div>'}
function proposalBuilder(hasProp){let d=propDraft();let briefs=allBriefs();let artistDefault=d.artist||(USERNAMES[state.chatTo]?state.chatTo:(get(STORE.signup,{}).username||''));let rows=d.labels.map((l,i)=>'<div class="form-group"><label>LINE ITEM '+(i+1)+'</label><input class="field" data-prop-label value="'+safe(l)+'" placeholder="e.g. Full-body character, colored" maxlength="90"></div><div class="form-group"><label>PRICE (USD)</label><input class="field" data-prop-price type="number" min="1" max="100000" step="0.01" value="'+safe(d.prices[i]||'')+'" placeholder="150"></div>').join('');let form='<form id="proposalForm" class="form-grid"><div class="form-group"><label for="pArtist">ARTIST NAME</label><input id="pArtist" class="field" value="'+safe(artistDefault)+'" maxlength="70" placeholder="The artist making this offer"></div><div class="form-group"><label for="pBrief">FOR WHICH BRIEF?</label><select id="pBrief" class="field"><option value="">Custom commission (no brief)</option>'+briefs.map(b=>'<option value="'+safe(b.id)+'"'+(String(b.id)===String(d.briefId)?' selected':'')+'>'+safe(b.title)+'</option>').join('')+'</select></div>'+rows+'<div class="full actions" style="margin:0"><button type="button" class="mini-btn" data-action="prop-add-row">+ ADD LINE ITEM</button>'+(d.labels.length>1?'<button type="button" class="mini-btn" data-action="prop-remove-row">− REMOVE LAST ITEM</button>':'')+'</div><div class="form-group"><label for="pDays">DELIVERY ESTIMATE (DAYS)</label><input id="pDays" class="field" type="number" min="1" max="365" value="'+safe(d.days)+'"></div><div class="form-group"><label for="pRevisions">REVISION ROUNDS INCLUDED</label><input id="pRevisions" class="field" type="number" min="0" max="20" value="'+safe(d.revisions)+'"></div><div class="form-group full"><label for="pRevNote">WHAT COUNTS AS A REVISION?</label><input id="pRevNote" class="field" value="'+safe(d.revNote)+'" maxlength="200" placeholder="e.g. Pose and palette changes count; a new character is a new item"></div><div class="form-group full"><label>STANDARD ADD-ONS TO OFFER</label><div class="prop-offers"><label><input type="checkbox" id="pRush"'+(d.rush?' checked':'')+'> ✦ Rush (+100% of base)</label><label><input type="checkbox" id="pPrivacy"'+(d.privacy?' checked':'')+'> 🔒 Privacy (+50% of base)</label><label><input type="checkbox" id="pCommercial"'+(d.commercial?' checked':'')+'> 💼 Commercial use (×2–3 of base)</label></div></div><div class="form-group"><label for="pMult">COMMERCIAL MULTIPLIER</label><select id="pMult" class="field"><option'+(String(d.mult)==='2'?' selected':'')+'>2</option><option'+(String(d.mult)==='2.5'?' selected':'')+'>2.5</option><option'+(String(d.mult)==='3'?' selected':'')+'>3</option></select></div><div class="form-group"><label>YOUR TIER (FEE SHOWN BEFORE ACCEPTANCE)</label><p class="form-note" style="margin:0">'+safe(currentArtistTier())+' — '+TIER_FEES[currentArtistTier()]+'% platform fee. The buyer sees the fee and what you keep before anyone accepts.</p></div><div class="full"><button class="primary" type="submit">SEND PROPOSAL 📋</button><p id="propMsg" style="margin-top:10px;line-height:1.6" role="alert"></p><p class="form-note">Demo builder — proposals live in this browser only. Proposal text passes the same safety screen as bios.</p></div></form>';if(hasProp)return '<details class="prop-builder"><summary>📋 BUILD ANOTHER PROPOSAL</summary>'+form+'</details>';return '<div class="prop-builder open"><h3 style="margin:0 0 4px">📋 BUILD A PROPOSAL</h3><p class="meta" style="margin-bottom:14px">Itemized, honest, in-thread — the pitch becomes a real offer.</p>'+form+'</div>'}
function briefCard(b,inWorld){let n=briefPitches(b);let sm=strongMatches(b);let matchRow=sm.length?'<div class="match-row"><span class="match-k">✦ STRONG MATCH — ARTISTS IN '+safe(b.category).toUpperCase()+'</span><div class="match-list">'+sm.map(function(nm){return '<span class="match-chip"><span class="match-mono">'+safe(monogram(nm))+'</span><b>'+safe(nm)+'</b><button class="mini-btn" data-action="contact" data-artist="'+safe(nm)+'">MESSAGE ✉</button></span>'}).join('')+'</div></div>':'';return `<article class="panel brief-card"><div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><span class="chip">✦ ${safe(b.category)}</span>${b.mine?'<span class="badge" style="background:#1d5c38;color:#b8ffd2">✦ YOUR BRIEF</span>':'<span class="badge">EXAMPLE BRIEF</span>'}${inWorld?'<span class="badge world-badge">✦ MATCHES YOUR CATEGORIES</span>':''}${b.type==='surprise'?'<span class="badge surprise-badge">✦ SURPRISE ME · FIXED · NO REVISIONS</span>':''}</div><h3>${safe(b.title)}</h3><div class="brief-meta"><span class="chip"><span class="dollar">$</span> Budget ${money(b.budget)}</span><span class="chip">◷ ${safe(b.timeline)}</span>${b.type==='surprise'?'<span class="chip">✦ Artist has creative freedom</span>':''}</div><p class="brief-details">${safe(b.details)}</p>${matchRow}<div class="brief-foot"><div class="brief-buyer"><div class="brief-avatar">${safe((b.buyer||'C').charAt(0))}</div><div><b style="color:#fff">${safe(b.buyer)}</b><p class="meta">Collector · ${n} pitch${n===1?'':'es'} so far</p></div></div>${b.mine?'<span class="meta">Pitches land in your Messages</span>':`<button class="outline" data-action="pitch" data-artist="${safe(b.buyer)}" data-brief="${safe(b.id)}">PITCH ✉</button>`}</div></article>`}
function board(){let cat=state.boardCategory||'All categories';let briefs=allBriefs().filter(b=>cat==='All categories'||b.category===cat);let acct=get(STORE.signup,{});let poster=acct.username?acct.username:'Guest collector';let cards=briefs.map(b=>briefCard(b)).join('');return `<div class="page-hero grotto-hero"><div class="shell"><div class="eyebrow">The Commission Board</div><h1 class="page-title">ASK FOR THE <span class="paint">IMPOSSIBLE.</span></h1><p class="sub">Dreaming of a piece that does not exist yet? Post the brief. Artists read the wall, pick the dreams they love, and pitch you right here — the conversation becomes the commission.</p><div class="actions"><button class="primary" data-action="scrollto" data-target="post-brief">POST A BRIEF ↗</button><a class="outline" href="#/artists" style="text-decoration:none;display:inline-flex;align-items:center">MEET THE ARTISTS →</a></div></div></div><section class="section"><div class="shell"><div class="section-top"><div><div class="eyebrow">Open briefs</div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">THE <span class="paint">WALL.</span></h2></div><p class="meta" style="max-width:340px">Example briefs show how the board works — real collector briefs open with the Founding 100 at launch. Briefs you post appear here on this browser.</p></div><div class="pills">${['All categories',...CATEGORIES].map(c=>`<button class="pill ${c===cat?'active':''}" data-action="board-cat" data-cat="${safe(c)}" style="--pill-hue:${catHue(c)}"${c===cat&&PRISM_CATS.indexOf(c)>=0?' data-prism="1"':''}>${safe(c)}</button>`).join('')}</div>${yourBoardStrip()}${briefs.length?`<div class="brief-grid">${cards}</div>`:'<div class="empty">No briefs in this category yet. Yours could be the first — post it below.</div>'}</div></section><section class="section alt" id="post-brief"><div class="shell two-col"><div><h2 class="section-title" style="font-size:clamp(30px,4vw,46px)">POST A <span class="paint">BRIEF.</span></h2><p class="sub" style="margin-bottom:16px">Tell the wall what you are dreaming of. Keep contact details out of the brief — conversations stay here, where they are protected.</p><div class="panel"><form id="briefForm" class="form-grid"><div class="form-group full"><label for="bfTitle">WHAT DO YOU WANT MADE? *</label><input id="bfTitle" class="field" name="title" placeholder="e.g. A portrait of my grandmother's garden — or an emote pack for your stream" required maxlength="110"></div><div class="form-group full"><label>BRIEF TYPE *</label><div class="brief-types"><label class="type-card"><input type="radio" name="briefType" value="standard" checked> <b>STANDARD</b><span>Full brief — details, timeline, revisions agreed in the thread.</span></label><label class="type-card"><input type="radio" name="briefType" value="surprise"> <b>SURPRISE ME</b><span>Fixed price · no revisions · the artist has creative freedom (Skeb-style).</span></label></div></div><div class="form-group full"><label>GAMING-NATIVE? START FROM A SHAPE</label><div class="pills" style="margin:0">${['Emote pack','Stream overlay','Avatar / VTuber art','OC / character'].map(g=>`<button type="button" class="pill" data-action="brief-idea" data-idea="${g}">${g}</button>`).join('')}</div><p class="form-note">Tap a shape to pre-fill your brief — emote packs, stream overlays, avatar / VTuber art and OC / character commissions are royalty here.</p></div><div class="form-group"><label for="bfCategory">CATEGORY *</label><select id="bfCategory" class="field" name="category">${CATEGORIES.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="form-group"><label for="bfBudget">BUDGET (USD) *</label><input id="bfBudget" class="field" name="budget" type="number" min="1" max="100000" step="1" placeholder="300" required></div><div class="form-group full"><label for="bfTimeline">TIMELINE *</label><select id="bfTimeline" class="field" name="timeline"><option>This week</option><option>Within a month</option><option>1–3 months</option><option>No rush — when it is right</option></select></div><div class="form-group full"><label for="bfDetails">THE DETAILS *</label><textarea id="bfDetails" class="field" name="details" placeholder="Size, colors, the story behind it — anything that helps an artist picture your piece." required maxlength="700"></textarea></div><div class="full"><button class="primary" type="submit">POST MY BRIEF ✦</button><p id="briefMsg" style="margin-top:10px;line-height:1.6" role="alert"></p><p class="form-note">Posting as <b style="color:#fff">${safe(poster)}</b>${acct.username?'':' — sign up on the Sell page to post under your own name'}. Your brief passes the same safety check as every bio: no contact info, no rough language.</p></div></form></div></div><aside><div class="steps" style="display:block"><div class="step"><span class="number">01</span><h3>POST THE DREAM</h3><p>Name the piece, the budget, and the moment it is for. Honest briefs get honest pitches.</p></div><div class="step" style="margin-top:14px"><span class="number">02</span><h3>ARTISTS PITCH YOU</h3><p>Artists who love your brief open a thread with their idea, their price, and their timeline.</p></div><div class="step" style="margin-top:14px"><span class="number">03</span><h3>TALK. AGREE. COMMISSION.</h3><p>The thread holds the whole story — idea, agreement, progress, delivery. The conversation is the commission.</p></div></div></aside></div></section>`}
function login(){let known=get(STORE.known,null);let active=get(STORE.signup,{});let acctList=accountRows(active.username||'');return `<div class="page-hero" style="--ph:#8B7CFF"><div class="shell"><div class="eyebrow">Welcome back</div><h1 class="page-title">STEP BACK <span class="paint">IN.</span></h1><p class="sub">Your stage is right where you left it.</p></div></div><section class="section"><div class="shell"><div class="panel" style="max-width:560px;margin:auto"><h2 class="section-title" style="font-size:30px">LOG <span class="paint">IN.</span></h2><p class="sub" style="margin:10px 0 16px">${known?`An account lives on this device: <b style="color:#fff">@${safe(known.username||'')}</b> — type your email and username to step back in.`:`Type the email and username you signed up with, and step back in.`}</p>${acctList}<form id="loginForm" class="form-grid"><div class="form-group full"><label for="liEmail">EMAIL ADDRESS *</label><input id="liEmail" class="field" name="email" type="email" placeholder="you@example.com" required></div><div class="form-group full"><label for="liUsername">USERNAME *</label><input id="liUsername" class="field" name="username" placeholder="your.username" required></div><div class="full"><button class="primary" type="submit" style="width:100%">LOG IN ✦</button><p id="loginMsg" style="margin-top:10px;line-height:1.6" role="alert"></p><p class="form-note">New to Painted Python? <a class="text-link" href="#/sell">Create your account</a> — it takes about a minute.</p></div></form></div></div></section>`}
function account(){let acct=get(STORE.signup,null);let example=!acct;let name=example?'Nova Reyes':(acct.username||'Your Studio');let handle=example?'@novareyes':(acct.username?'@'+acct.username:'');let email=example?'nova@novareyes.art':acct.email;let mine=example?all().filter(a=>a.artist==='Nova Reyes'):get(STORE.listings,[]);let rating=example?RATINGS['Nova Reyes']:null;let pr=example?'She/Her':(acct.pronouns||'');let others=example?[]:getAccounts().filter(function(x){return low(x.username)!==low(acct.username)});let switchHtml=(!example&&others.length)?'<div class="panel" style="margin-top:16px"><h3>Switch account</h3><p class="sub" style="margin:8px 0 4px;font-size:13px">More than one artist on this device? Jump between studios in one tap.</p>'+others.map(function(r){return '<div style="display:flex;gap:10px;align-items:center;padding:9px 0;border-top:1px solid #3d3150"><div style="flex:1"><b style="color:#fff">'+safe(r.username)+'</b><p class="meta" style="color:var(--cyan)">@'+safe(low(r.username))+'</p></div><button class="small-btn" data-action="login-as" data-u="'+safe(r.username)+'">SWITCH</button></div>'}).join('')+'</div>':'';let photos=(mine.length?mine:all()).slice(0,6);let feed=mine.length?mine:all().slice(0,2);let posts=feed.map(a=>'<div class="panel" style="margin-bottom:16px"><div style="display:flex;gap:10px;align-items:center;margin-bottom:12px"><div class="artist-avatar avatar-mono" style="width:42px;height:42px;font-size:20px;overflow:hidden">'+avatarInner(example,name)+'</div><div><b style="color:#fff">'+safe(name)+'</b><p class="meta">'+safe(a.tag||'Just listed')+' · '+safe(a.category)+'</p></div></div>'+artCard(a)+'</div>').join('');return '<section class="section" style="padding-top:22px"><div class="shell"><div style="height:190px;border-radius:18px;background-image:url(assets/scales-bg-ballpython.jpg);background-size:cover;background-position:center;border:1px solid #3d3150"></div><div style="display:flex;gap:18px;align-items:flex-end;flex-wrap:wrap;padding:0 14px;margin-top:-52px"><div class="artist-avatar avatar-mono" style="width:118px;height:118px;font-size:56px;border:4px solid #17102a;background:#241843;overflow:hidden">'+avatarInner(example,name)+'</div><div style="flex:1;min-width:230px;padding-bottom:6px"><h1 class="page-title" style="font-size:42px">'+safe(name)+'</h1><p class="meta" style="margin-top:2px">'+safe(email)+' · '+(example?'Digital artist · Serpent Circle':'Artist studio')+(handle?' · '+safe(handle):'')+(pr?' · '+safe(pr):'')+'</p><div style="margin-top:9px">'+ageBadge(example?AGES[name]:ageFromDob(acct.dob,new Date()),true)+'</div><div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap"><span class="badge">PYTHON MEMBER</span>'+(example?'<span class="badge" style="background:#FFC94D;color:#241203">#1 WORLD SERPENT</span>':'<span class="badge" style="background:#1d5c38;color:#b8ffd2">13+ VERIFIED ✔</span>')+'</div></div><div style="display:flex;gap:10px;padding-bottom:10px"><a class="primary" href="#/sell" style="text-decoration:none;padding:12px 18px;border-radius:12px">+ ADD ARTWORK</a><a class="outline" href="#/messages" style="text-decoration:none;padding:12px 18px;border-radius:12px">MESSAGES ✉</a>'+(example?'':'<button class="outline" data-action="logout" style="padding:12px 18px;border-radius:12px">LOG OUT</button>')+'</div></div><div style="display:flex;gap:6px;flex-wrap:wrap;border-top:1px solid #3d3150;border-bottom:1px solid #3d3150;padding:10px 6px;margin-top:8px"><button class="small-btn" data-action="scrollto" data-target="acct-feed">Listings</button><button class="small-btn" data-action="scrollto" data-target="acct-intro">About</button><button class="small-btn" data-action="scrollto" data-target="acct-orders">Orders</button><button class="small-btn" data-action="scrollto" data-target="acct-reviews">Reviews</button><span class="meta" style="margin-left:auto;align-self:center">'+mine.length+' listings · '+(example?'3':'0')+' orders · '+likes().length+' saved</span></div>'+(example?'<p class="meta" style="margin-top:12px">Example account — this is what an artist’s profile looks like. Sign up on the Sell page and this page becomes yours. Already have an account on this device? <a class="text-link" href="#/login">LOG IN →</a></p>':'')+'<div class="two-col" style="margin-top:20px;align-items:start"><div>'+(example?'':'<div class="panel" style="margin-bottom:16px"><h3>EDIT YOUR PROFILE</h3><p class="sub" style="margin:8px 0 12px;font-size:13px">Your bio and profile picture pass an <b style="color:#fff">AI safety check</b> before they appear — nothing public goes up unscreened.</p><form id="profileForm"><label for="pfPic" style="display:block;font-size:12px;font-weight:900;margin-bottom:8px">PROFILE PICTURE</label><input id="pfPic" class="field" type="file" accept="image/*" style="margin-bottom:6px"><p class="form-note" style="margin-bottom:12px">JPG or PNG, up to 8 MB. Square pictures frame best.</p><label for="pfBio" style="display:block;font-size:12px;font-weight:900;margin-bottom:8px">YOUR BIO</label><textarea id="pfBio" class="field" maxlength="300" rows="3" placeholder="Tell the world who you are…">'+safe(get(STORE.profile,{}).bio||'')+'</textarea><p class="form-note" style="margin:6px 0 12px">Up to 300 characters. Keep contact details out of your bio — conversations stay here, where they\'re protected.</p><button class="primary" type="submit" style="width:100%">SAVE — RUN THE SAFETY CHECK</button><p id="pfMsg" style="margin-top:10px;line-height:1.6" role="alert"></p></form></div>')+'<div class="panel" id="acct-intro" style="margin-bottom:16px"><h3>Intro</h3>'+(example?'<p style="line-height:1.75;margin-top:8px;font-style:italic">“I paint impossible color and friendly monsters. Commissions are open — message me and let\'s make something loud.”</p>':(get(STORE.profile,{}).bio?'<p style="line-height:1.75;margin-top:8px;font-style:italic">“'+safe(get(STORE.profile,{}).bio)+'”</p>':''))+'<p style="line-height:1.9;margin-top:8px">✦ '+(example?'Digital artist painting impossible color':'Independent artist studio')+'<br>📍 '+(example?'Austin, Texas':'Painted Python')+'<br>✦ Member of the Serpent Circle'+(pr?'<br>🗣 Pronouns: '+safe(pr):'')+'<br>✦ Joined Painted Python 2026<br>🛡 Age band shown publicly — never a birthdate. Minor accounts get extra protections.</p></div><div class="panel" id="acct-reviews" style="margin-bottom:16px"><h3>Rating &amp; reviews</h3>'+(rating?'<div style="margin-top:8px">'+stars(rating.r)+' <b style="color:#fff">'+rating.r+'</b><p class="meta">'+rating.n+' customer reviews</p></div><p style="line-height:1.65;font-style:italic;margin-top:10px">“'+safe((REVIEWS['Nova Reyes']||[])[0].q)+'”</p><p class="meta">— Maya R. · Custom portrait</p>':'<p class="sub" style="margin-top:8px">No ratings yet — your first sale starts your climb to World Serpent.</p>')+'</div><div class="panel"><h3>Photos</h3><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px">'+photos.map(a=>'<div class="acct-photo" style="background:'+a.bg+'">'+(a.img?'<img src="'+a.img+'" alt="">':safe(a.symbol||'◉'))+'</div>').join('')+'</div></div></div><div><div id="acct-feed">'+(mine.length||example?posts:'<div class="panel" style="margin-bottom:16px"><p class="sub">No posts yet. Your stage is empty — for about five minutes.</p><div class="actions" style="margin-top:12px"><a class="primary" href="#/sell" style="text-decoration:none;padding:12px 18px;border-radius:12px">LIST YOUR FIRST MASTERPIECE ↗</a></div></div>')+'</div><div class="panel" id="acct-orders"><h3>Recent orders</h3>'+(example?'<p style="line-height:1.9;margin-top:8px">• <b style="color:#fff">Chromatic Serpent</b> — delivered ✔ Maya R. left a ★★★★★ review<br>• <b style="color:#fff">Custom portrait</b> — in the studio, ships Friday<br>• <b style="color:#fff">Neon Botanica (print)</b> — delivered ✔</p>':'<p class="sub" style="margin-top:8px">No orders yet. When a customer buys your art, it lands here — with delivery status and their review.</p>')+'</div><div class="panel" style="margin-top:16px"><h3>My membership</h3><p style="line-height:1.8;margin-top:8px"><b style="color:#fff">Python</b> — $9.99/mo · 5% per sale<br>Unlimited listings · commissions · analytics</p><div class="actions" style="margin-top:10px"><a class="outline" href="#/membership" style="text-decoration:none;padding:11px 16px;border-radius:12px">MANAGE MEMBERSHIP</a></div><p class="form-note" style="margin-top:10px">Example view — billing is not active in this preview.</p></div>'+switchHtml+'</div></div></div></section>'}
/* FOUNDING 100 (queue 3, 2026-10-25) — recruitment machine: honest live counter,
   application intake (slither-founding-v1), mix targets, preview-artist wall,
   shareable artist profiles. No fabricated founders or counts, ever. */
function foundingApps(){return get(STORE.founding,[])}
function foundingSeatsClaimed(){/* PRODUCTION: this is the single swap point — the
  engine replaces this body with the real server cohort count; the page reads
  only this function. In the demo it counts real local applications, nothing else. */
  return foundingApps().length}
function foundingNorm(s){return String(s||'').trim().toLowerCase().replace(/^@+/,'')}
const FOUNDING_LOCK_SAVE=(9.99-6)*24; /* $95.76 across the 24-month lock */
const MIX_LANES=[
 {key:'painters',label:'PAINTERS',target:40,blurb:'The anchors — originals that hold a wall and stop a scroll.',cats:['Painting']},
 {key:'illustrators',label:'ILLUSTRATORS & PRINT',target:35,blurb:'Feeds, fandoms, editions — the image-makers people collect in series.',cats:['Illustration','Drawing & Sketch','Printmaking','Prints & Posters','Anime & Manga Style','Character Design']},
 {key:'commissions',label:'COMMISSION ARTISTS',target:25,blurb:'The Board’s heartbeat — artists who make the thing that does not exist yet, for one person.',cats:['Commissions','Custom Portraits','Pet Portraits']}];
function mixLaneFor(cat){for(let l of MIX_LANES)if(l.cats.indexOf(cat)>=0)return l.key;return 'other'}
function submitFoundingApplication(d){
 let name=String(d.name||'').trim(),email=String(d.email||'').trim(),category=String(d.category||''),work=String(d.work||'').trim(),why=String(d.why||'').trim(),comm=String(d.commissions||'Yes — commissions open');
 if(name.length<2)return{ok:false,why:'fields',msg:'Tell us your artist name or username — founders are named, never numbered.'};
 if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))return{ok:false,why:'fields',msg:'That email does not look complete — it is how the founding list reaches you at launch.'};
 if(CATEGORIES.indexOf(category)<0)return{ok:false,why:'fields',msg:'Pick the category closest to your primary craft.'};
 if(work.length<4)return{ok:false,why:'fields',msg:'Show us your work — a portfolio link, or a few lines about what you make.'};
 let bc=bioCheck(name+' '+why);
 if(!bc.ok)return{ok:false,why:bc.why,msg:bc.why==='contact'?'🛡 Contact details can’t ride in your name or why-line — your email stays private inside the application itself.':'🛡 Our safety check flagged words in your application, so it has not been stored. Try a kinder wording — the house stays welcoming.'};
 /* The work field may BE a portfolio link: bioCheck's contact verdict is expected
    there and allowed, because an application is private — it is never published.
    The language check still applies in full. */
 let wc=bioCheck(work);
 if(!wc.ok&&wc.why==='language')return{ok:false,why:'language',msg:'🛡 Our safety check flagged words in your work description, so it has not been stored. Try a kinder wording.'};
 if(!wc.ok&&wc.why==='contact'&&!/(https?:\/\/|www\.)[^\s]+/i.test(work))return{ok:false,why:'contact',msg:'🛡 Contact details can’t ride in your application text — a portfolio link is welcome, but emails and phone numbers stay out; the application itself carries your email privately.'};
 let apps=foundingApps(),nu=foundingNorm(name),ne=email.toLowerCase();
 if(apps.some(a=>foundingNorm(a.name)===nu||String(a.email||'').toLowerCase()===ne))return{ok:false,why:'dupe',msg:'This artist name or email already has a founding application on this device — one application per artist, and yours is already on the list here.'};
 let app={id:Date.now(),name:name,email:email,category:category,work:work,commissions:comm,why:why,lane:mixLaneFor(category),at:Date.now()};
 set(STORE.founding,[app,...apps]);addAlert('founding','✦ Founding 100 application received — '+app.name+' · '+app.category+'. That is seat '+foundingSeatsClaimed()+' of 100 claimed on this device.','#/founding100');
 return{ok:true,app:app}}

/* ADDICTION LOOP (queue 10, DOMINANCE-PLAN Beast Mode) — Fresh Today rail,
   Your Board, real alerts. House rails: every count on these surfaces traces
   to a stored record; no fake notifications, no invented "new" content. */
function dayIndex(){return Math.floor(Date.now()/864e5)}
function freshPieces(day){let items=all();if(!items.length)return[];let d=(day==null?dayIndex():day);let off=((d%items.length)+items.length)%items.length;let out=[];for(let i=0;i<Math.min(4,items.length);i++)out.push(items[(off+i)%items.length]);return out}
function spotlightNames(){return [...new Set(all().map(a=>a.artist))]}
function spotlightWeek(){return Math.floor(Date.now()/6048e5)}
function spotlightAt(weeksAgo){let names=spotlightNames();if(!names.length)return '';let ix=((spotlightWeek()-(weeksAgo||0))%names.length+names.length)%names.length;return names[ix]}
function spotlightArtist(){return spotlightAt(0)}
/* PHASE 3 — THE ADDICTION ENGINE (Daily Edit · Commission Match · Follows).
   Honesty law: every signal below is computed ONLY from stored records
   (slither-follows-v1, slither-likes-v1, slither-alerts-v1) plus the
   catalog itself. Nothing is invented: no scores, no percentages, no
   phantom activity. */
function follows(){let f=get(STORE.follows,[]);return Array.isArray(f)?f:[]}
function isFollowing(name){return follows().indexOf(name)>=0}
function toggleFollow(name){let f=follows();let on=f.indexOf(name)<0;set(STORE.follows,on?[...f,name]:f.filter(function(x){return x!==name}));return on}
function followBtn(name){let on=isFollowing(name);return '<button class="outline follow-btn'+(on?' following':'')+'" data-action="follow" data-artist="'+safe(name)+'" aria-pressed="'+(on?'true':'false')+'">'+(on?'✦ FOLLOWING':'✦ FOLLOW')+'</button>'}
function savedCategories(){let ids=likes();let counts={};all().forEach(function(a){if(ids.indexOf(a.id)>=0)counts[a.category]=(counts[a.category]||0)+1});return Object.keys(counts).sort(function(x,y){return counts[y]-counts[x]||(x<y?-1:1)})}
/* YOUR DAILY EDIT — a pure function of (day, stored signals, catalog):
   the deterministic daily rotation (freshPieces) reordered by real
   signals only — followed artists first (boost 2), saved categories
   next (boost 1), stable by rotation order inside a tier. Each boosted
   piece carries its honest why-label; unboosted pieces carry none. */
function dailyEdit(day){let base=freshPieces(day);let f=follows();let sc=savedCategories();let scored=base.map(function(a,i){let boost=0,why='';if(f.indexOf(a.artist)>=0){boost=2;why='Because you follow '+a.artist}else if(sc.indexOf(a.category)>=0){boost=1;why='More '+a.category+' — you save '+a.category.toLowerCase()+' work'}return{a:a,ix:i,boost:boost,why:why}});scored.sort(function(x,y){return y.boost-x.boost||x.ix-y.ix});return scored}
function artistCategories(name){let cats=[];all().forEach(function(a){if(a.artist===name&&cats.indexOf(a.category)<0)cats.push(a.category)});return cats}
/* COMMISSION MATCH — category overlap only. Order: the board's own
   standing (rating, then review count), then name. No match scores. */
